# -*- coding: utf-8 -*-
"""단체예약 예시 일정표·예상 견적 계산 (모든 단가는 data/pricing.json, 모의데이터)."""
import math, datetime
from .kb import won

DISCLAIMER = ('본 견적은 입력하신 조건을 기준으로 산출한 예시이며, '
              '실제 예약 가능 여부 및 최종 금액은 담당자 확인이 필요합니다.')
WD = ['월', '화', '수', '목', '금', '토', '일']

def _hm(minutes):
    return '{:02d}:{:02d}'.format(minutes // 60, minutes % 60)

def night_tier(d, rules):
    """숙박일(d) 요금 구분: peak(성수기) / weekend(주말·공휴일 전일) / weekday(비수기 주중)."""
    ps = rules.get('peak_season')
    if ps and len(ps) == 2:
        md = '{:02d}-{:02d}'.format(d.month, d.day)
        if ps[0] <= md <= ps[1]:
            return 'peak'
    hol = set(rules.get('holidays') or [])
    if d.weekday() in rules.get('weekend_days', [4, 5]) or (d + datetime.timedelta(days=1)).isoformat() in hol:
        return 'weekend'
    return 'weekday'

def night_price(room, tier, rate):
    if tier == 'weekday':
        return room['price']
    if room.get('price_peak'):
        return room['price_peak']
    return room['price'] * (1.0 + rate)

def pick_room(pricing, pax, choice=None, start=None, nights=1):
    rooms = pricing['rooms']
    rules = pricing.get('rules') or {}
    if choice:
        for r in rooms:
            if r['name'] == choice or r['id'] == choice:
                return r
    best, best_cost = None, None
    for r in rooms:                       # 추천: 총 객실비가 가장 낮은 유형
        if start:
            per = sum(night_price(r, night_tier(start + datetime.timedelta(days=n), rules), rules.get('weekend_surcharge_rate', 0)) for n in range(max(1, nights or 1)))
        else:
            per = r['price']
        cost = math.ceil(pax / float(r['capacity'])) * per
        if best is None or cost < best_cost:
            best, best_cost = r, cost
    return best

def _t2m(v):
    """'HH:MM' -> 분. 형식이 다르면 None."""
    try:
        h, m = str(v).split(':'); return int(h) * 60 + int(m)
    except (ValueError, AttributeError):
        return None

HALL_OPEN, HALL_CLOSE = 9 * 60, 21 * 60       # 시설 이용 가능 시간 09:00~21:00
MEAL_NAME = {'breakfast': '조식', 'lunch': '중식', 'dinner': '석식'}
MEAL_TIME = {'breakfast': 8 * 60, 'lunch': 12 * 60, 'dinner': 18 * 60}

def hall_cost(h, hours):
    """기본 2시간 요금 + 추가 1시간당 요금. 2시간 미만도 기본 요금."""
    hours = max(2, int(hours or 2))
    extra = int(h.get('extra') or 0)
    return int(h['price']) + extra * (hours - 2), hours

def build(pricing, slots):
    """slots: start, nights, pax, room(단일, 구버전)/rooms[list], programs[list of id], meals[list of id](구버전)/meal_plan{일차:[id]},
    first_lunch, hall(단일, 구버전)/halls[{id,day,start,hours}]."""
    rules = dict(pricing.get('rules') or {})
    wrate = rules.get('weekend_surcharge_rate', 0.2)
    nights = int(slots.get('nights') or 0)
    pax = int(slots['pax'])
    start = slots.get('start')
    days = nights + 1
    prog = {p['id']: p for p in pricing['programs']}
    meal = {m['id']: m for m in pricing['meals']}
    chosen = [prog[i] for i in slots.get('programs', []) if i in prog]
    meals = [i for i in slots.get('meals', []) if i in meal]
    first_lunch = bool(slots.get('first_lunch')) and 'lunch' in meals  # (구버전) 도착 후 첫날 점심 식사 포함
    meal_plan = slots.get('meal_plan')
    hall_by_id = {h['id']: h for h in pricing['halls']}
    bookings = []
    if slots.get('halls') is not None:
        for b in slots['halls']:
            if b.get('id') in hall_by_id: bookings.append((hall_by_id[b['id']], b))
    elif slots.get('hall') and slots['hall'] in hall_by_id:
        bookings.append((hall_by_id[slots['hall']], {'id': slots['hall'], 'day': None, 'start': None, 'hours': None}))   # 구버전: 시간 미정

    def day_meals(d):
        """d(0부터)번째 날의 식사 목록. 일차별 선택(meal_plan)이 있으면 그대로, 없으면 구버전 규칙."""
        first, last = d == 0, d == days - 1
        if meal_plan is not None:
            got = set(meal_plan.get(d + 1) or meal_plan.get(str(d + 1)) or [])
        else:
            got = set()
            if 'breakfast' in meals and not first: got.add('breakfast')
            if 'lunch' in meals and (not (first and nights > 0) or first_lunch): got.add('lunch')
            if 'dinner' in meals and (not last or nights == 0): got.add('dinner')
        return [i for i in ('breakfast', 'lunch', 'dinner') if i in got and i in meal]

    # ---- 일정표 ----
    schedule = []
    queue = list(chosen)
    for d in range(days):
        date_label = ''
        if start:
            dd = start + datetime.timedelta(days=d)
            date_label = '{}.{}.({})'.format(dd.month, dd.day, WD[dd.weekday()])
        ev = []
        first, last = d == 0, d == days - 1
        dm = day_meals(d)
        if first:
            if nights > 0 and 'lunch' in dm:
                ev.append((11 * 60 + 30, '도착·안내센터 접수(점심 식사 후 15:00 이후 객실 입실)'))
            else:
                ev.append((10 * 60 if nights == 0 else 14 * 60, '도착·안내센터 접수' if nights == 0 else '도착·입실(15:00 이후 객실 이용)'))
        else:
            ev.append((8 * 60 + 30 if 'breakfast' not in dm else 9 * 60 + 30, '하루 일정 시작'))
        for mid in dm:
            ev.append((MEAL_TIME[mid], MEAL_NAME[mid]))
        for h, b in bookings:
            if b.get('day') is None:          # 구버전(시간 미정): 매일 표시
                ev.append((9 * 60 + 30 if not first or nights == 0 else 14 * 60, '{} 이용(교육·회의, 시간은 담당자와 협의)'.format(h['name'])))
            elif min(max(int(b['day']), 1), days) == d + 1:
                st = _t2m(b.get('start')) or HALL_OPEN
                hrs = max(2, int(b.get('hours') or 2))
                ev.append((st, '{} 이용 {}~{} ({}시간)'.format(h['name'], _hm(st), _hm(min(st + hrs * 60, 24 * 60)), hrs)))
        # 프로그램 배치: 오전 창 / 오후 창
        if first and nights > 0:
            windows = [(14 * 60 + 30, 17 * 60 + 30)]
        elif first:
            windows = [(10 * 60 + 30, 11 * 60 + 50), (13 * 60 + 30, 17 * 60)]
        elif last:
            windows = [(9 * 60 + 30, 11 * 60)]
        else:
            windows = [(9 * 60 + 30, 11 * 60 + 50), (13 * 60 + 30, 17 * 60)]
        for ws, we in windows:
            t = ws
            while queue and t + queue[0]['minutes'] <= we:
                p = queue.pop(0)
                ev.append((t, '{}({}분)'.format(p['name'], p['minutes'])))
                t += p['minutes'] + 20
        if last and nights > 0:
            ev.append((11 * 60, '퇴실·정산'))
        elif last:
            ev.append((17 * 60 + 30, '마무리·귀가'))
        ev.sort(key=lambda x: x[0])
        schedule.append({'day': d + 1, 'date': date_label, 'items': [{'time': _hm(t), 'title': s} for t, s in ev]})
    leftover = [p['name'] for p in queue]

    # ---- 견적 ----
    lines, warnings, room_unit = [], [], []
    if nights > 0:
        counts = slots.get('room_counts') or {}
        plan = []                                   # [(room, n_rooms, share_or_None)]
        for key, n in counts.items():
            for r in pricing['rooms']:
                if r['name'] == key or r['id'] == key:
                    if int(n) > 0: plan.append((r, int(n), None))
                    break
        if not plan:
            types = []
            for key in slots.get('rooms') or []:
                for r in pricing['rooms']:
                    if (r['name'] == key or r['id'] == key) and r not in types: types.append(r)
            if not types:
                types = [pick_room(pricing, pax, slots.get('room'), start, nights)]
            types = types[:max(1, min(len(types), pax))]
            k = len(types)
            for idx, room in enumerate(types):
                share = pax // k + (1 if idx < pax % k else 0)
                plan.append((room, int(math.ceil(share / float(room['capacity']))), share if k > 1 else None))
        for room, n_rooms, share in plan:
            total_room, wk, hi = 0.0, 0, 0
            one_off = one_peak = 0.0
            for n in range(nights):
                tier = night_tier(start + datetime.timedelta(days=n), rules) if start else 'weekday'
                total_room += n_rooms * night_price(room, tier, wrate)
                if tier == 'weekday': wk += 1; one_off += night_price(room, tier, wrate)
                else: hi += 1; one_peak += night_price(room, tier, wrate)
            room_unit.append({'name': room['name'], 'off': int(round(one_off)), 'peak': int(round(one_peak))})
            note = ''
            if room.get('price_peak'):
                if start:
                    parts = []
                    if wk: parts.append('비수기 주중 {}박({:,}원)'.format(wk, room['price']))
                    if hi: parts.append('성수기·주말 {}박({:,}원)'.format(hi, room['price_peak']))
                    note = ' + '.join(parts)
                else:
                    note = '일자 미정: 비수기 주중 요금 기준(성수기·주말 {:,}원)'.format(room['price_peak'])
            elif hi:
                note = '가산 요일 숙박 {}박 {}% 가산 포함'.format(hi, int(round(wrate * 100)))
            elif not start:
                note = '일자 미정: 주중 요금 기준'
            if share is not None:
                note = (note + ' / ' if note else '') + '배정 인원 {}명'.format(share)
            lines.append({'item': '객실 {}'.format(room['name']), 'unit': room['price'], 'qty': '{}실×{}박'.format(n_rooms, nights), 'amount': int(round(total_room)), 'note': note, 'photo': room.get('photo'), 'kind': 'room'})
        cap = sum(r['capacity'] * n for r, n, _ in plan)
        if counts and plan:
            if cap < pax:
                warnings.append('선택하신 객실의 정원 합계({}명)가 인원({}명)보다 적습니다. 객실을 추가하시거나 담당자와 조정해 주세요.'.format(cap, pax))
            elif cap - pax >= max(r['capacity'] for r, _, _ in plan):
                warnings.append('선택하신 객실의 정원 합계({}명)가 인원({}명)보다 많이 큽니다. 객실 수를 줄일 수 있는지 확인해 보세요.'.format(cap, pax))
        elif len(plan) > 1:
            warnings.append('여러 객실 유형을 선택하셔서 인원을 유형별로 균등하게 나누어 계산했습니다. 유형별 인원 배분은 담당자와 조정이 필요합니다.')
    for p in chosen:
        lines.append({'item': '프로그램 · ' + p['name'], 'unit': p['price'], 'qty': '{}명'.format(pax), 'amount': p['price'] * pax, 'note': '{}분'.format(p['minutes']), 'photo': p.get('photo'), 'kind': 'program'})
    kids = slots.get('kids') or {}
    tiers = {t['id']: t for t in (pricing.get('meal_tiers') or [])}
    n_child = int(kids.get('child') or 0) if tiers else 0
    n_iw = int(kids.get('infant_with') or 0) if tiers else 0
    n_io = int(kids.get('infant_without') or 0) if tiers else 0
    n_adult = max(0, pax - n_child - n_iw - n_io)
    if n_child + n_iw + n_io > pax:
        warnings.append('어린이·영유아 인원의 합이 전체 인원보다 많아 성인 식사 인원을 0명으로 계산했습니다. 인원을 확인해 주세요.')
    total_meals = 0
    for mid in ('breakfast', 'lunch', 'dinner'):          # 식사 횟수는 일정표와 같은 규칙으로 계산
        cnt = sum(1 for d in range(days) if mid in day_meals(d))
        if cnt:
            total_meals += cnt
            lines.append({'item': '식사 · ' + meal[mid]['name'] + (' (성인)' if (n_child + n_iw + n_io) else ''), 'unit': meal[mid]['price'], 'qty': '{}명×{}회'.format(n_adult, cnt), 'amount': meal[mid]['price'] * n_adult * cnt, 'note': '', 'kind': 'meal'})
    if total_meals:
        for key, n, label in (('child', n_child, '어린이(36개월~만 13세 미만)'), ('infant_without', n_io, '영·유아(보호자 미동반)'), ('infant_with', n_iw, '영·유아(보호자 동반)')):
            if n:
                t = tiers[key]
                lines.append({'item': '식사 · ' + label, 'unit': t['price'], 'qty': '{}명×{}회'.format(n, total_meals), 'amount': t['price'] * n * total_meals, 'note': '무료' if t['price'] == 0 else '', 'kind': 'meal'})
    for h, b in bookings:
        amt, hrs = hall_cost(h, b.get('hours'))
        notes = []
        if b.get('day') is not None:
            st = _t2m(b.get('start')) or HALL_OPEN
            notes.append('{}일차 {}~{}'.format(min(max(int(b['day']), 1), days), _hm(st), _hm(min(st + hrs * 60, 24 * 60))))
        if pax > h['capacity']:
            notes.append('수용인원({}명) 초과 - 더 넓은 시설 확인 필요'.format(h['capacity']))
            warnings.append('{}: 수용인원({}명)을 초과합니다.'.format(h['name'], h['capacity']))
        if h.get('extra'):
            notes.append('기본 2시간 {:,}원 + 추가 1시간당 {:,}원'.format(h['price'], h['extra']))
        elif hrs > 2:
            notes.append('추가 시간 요금이 등록되어 있지 않아 기본 요금만 반영(담당자 확인 필요)')
            warnings.append('{}: 2시간을 넘는 이용 요금은 담당자 확인이 필요합니다.'.format(h['name']))
        if b.get('day') is None:
            qty = '기본 2시간' if h.get('extra') else '1식'
        else:
            qty = '{}시간'.format(hrs) if hrs <= 2 else '기본 2시간+추가 {}시간'.format(hrs - 2)
        lines.append({'item': '대관 · ' + h['name'], 'unit': h['price'], 'qty': qty, 'amount': amt, 'note': ' / '.join(notes), 'photo': h.get('photo'), 'kind': 'hall'})
    # 단체 할인(설정된 경우만): 가장 높은 구간 하나 적용
    best = None
    for dsc in rules.get('discounts') or []:
        if pax >= int(dsc.get('min_pax', 0)) and (best is None or dsc['rate'] > best['rate']):
            best = dsc
    if best:
        base = sum(l['amount'] for l in lines if l.get('kind') in best.get('scope', ['room', 'program']))
        if base:
            lines.append({'item': '단체 할인({}명 이상 {}%)'.format(best['min_pax'], int(round(best['rate'] * 100))), 'unit': 0, 'qty': '-', 'amount': -int(round(base * best['rate'])), 'note': '적용 대상: ' + '·'.join(best.get('scope', ['room', 'program'])), 'kind': 'discount'})
    total = sum(l['amount'] for l in lines)
    if leftover:
        warnings.append('선택하신 프로그램 중 시간 부족으로 일정표에 배치하지 못한 항목: ' + ', '.join(leftover) + ' (견적에는 포함됨, 담당자와 일정 조정 필요)')
    if not start:
        warnings.append('이용일이 확정되지 않아 주중 기준으로 계산했습니다.')
    return {'schedule': schedule, 'lines': lines, 'total': total, 'total_text': won(total), 'per_person_text': won(total / float(pax)),
            'warnings': warnings, 'disclaimer': DISCLAIMER, 'pax': pax, 'nights': nights, 'room_unit': room_unit}

def quote_text(q):
    out = ['[예시 일정표]']
    for d in q['schedule']:
        out.append('{}일차 {}'.format(d['day'], d['date']))
        for it in d['items']:
            out.append('  {}  {}'.format(it['time'], it['title']))
    out.append('')
    out.append('[예상 견적]')
    for l in q['lines']:
        out.append('  {} / {} / {}{}'.format(l['item'], l['qty'], won(l['amount']), ' ({})'.format(l['note']) if l['note'] else ''))
    out.append('  합계: {} (1인당 약 {})'.format(q['total_text'], q['per_person_text']))
    out.append('')
    out.append('※ ' + q['disclaimer'])
    return '\n'.join(out)

