# -*- coding: utf-8 -*-
"""이메일 발송. SMTP 환경변수가 없으면 outbox 폴더에 .eml 파일로 저장(모의 발송)하고 기록한다.
환경변수: SUMTALK_SMTP_HOST, SUMTALK_SMTP_PORT(기본 587), SUMTALK_SMTP_USER, SUMTALK_SMTP_PASS, SUMTALK_MAIL_FROM"""
import os, smtplib, ssl, re
from email.message import EmailMessage
from . import store

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'outbox')

def valid_email(a):
    return bool(re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', a or ''))

def send(to_addr, subject, body):
    if not valid_email(to_addr):
        return {'ok': False, 'mode': 'none', 'error': '이메일 주소 형식이 올바르지 않습니다.'}
    host = os.environ.get('SUMTALK_SMTP_HOST')
    msg = EmailMessage()
    msg['To'] = to_addr
    msg['From'] = os.environ.get('SUMTALK_MAIL_FROM', 'sumtalk@example.invalid')
    msg['Subject'] = subject
    msg.set_content(body)
    if host:
        try:
            port = int(os.environ.get('SUMTALK_SMTP_PORT', '587'))
            with smtplib.SMTP(host, port, timeout=15) as s:
                s.starttls(context=ssl.create_default_context())
                if os.environ.get('SUMTALK_SMTP_USER'):
                    s.login(os.environ['SUMTALK_SMTP_USER'], os.environ.get('SUMTALK_SMTP_PASS', ''))
                s.send_message(msg)
            store.execute('INSERT INTO outbox(ts,to_addr,subject,body,mode,status) VALUES(?,?,?,?,?,?)', (store.now(), to_addr, subject, body, 'smtp', '발송완료'))
            return {'ok': True, 'mode': 'smtp'}
        except Exception as e:  # SMTP 실패 시 outbox로 폴백
            err = str(e)
    else:
        err = None
    os.makedirs(OUT, exist_ok=True)
    fn = os.path.join(OUT, '{}_{}.eml'.format(store.now().replace(':', '').replace(' ', '_').replace('-', ''), re.sub(r'[^a-z0-9]', '_', to_addr.lower())))
    with open(fn, 'wb') as f:
        f.write(bytes(msg))
    store.execute('INSERT INTO outbox(ts,to_addr,subject,body,mode,status) VALUES(?,?,?,?,?,?)',
                  (store.now(), to_addr, subject, body, 'outbox(모의)', '저장됨(SMTP 미설정)' if err is None else 'SMTP 실패→저장: ' + err[:80]))
    return {'ok': True, 'mode': 'outbox', 'note': 'SMTP가 설정되지 않아 서버의 outbox 폴더에 저장했습니다(시연 모드).'}

