# -*- coding: utf-8 -*-
"""숲톡 민원AI 대화 엔진: 질문분류 -> 근거검색(RAG) -> 답변 / 담당자 상담 / 단체예약 흐름."""
import re, uuid, json, datetime, threading
from . import store, quote as quotelib, llm, mailer, penalty as penlib
from .kb import KnowledgeBase, won
from .nlp import jaccard, protect_hit

KB = KnowledgeBase()
SESSIONS = {}
_slock = threading.RLock()

STEPS = ['date', 'stay', 'pax', 'age', 'room', 'program', 'meal', 'kids', 'hall', 'notes']
STEP_LABEL = {'date': '희망 이용일', 'stay': '숙박(당일/박수)', 'pax': '인원', 'age': '연령대', 'room': '객실 유형',
              'program': '프로그램', 'meal': '식사', 'kids': '어린이·영유아(식비)', 'hall': '대관', 'notes': '기타 요청'}
AGES = ['어린이·청소년', '청년(20~30대)', '중장년(40~50대)', '60대 이상', '연령 혼합']
STAYS = ['당일(숙박 없음)', '1박 2일', '2박 3일', '3박 4일']
def _alias_re(name, aliases):
    toks = [name] + [w for w in re.split(r'[\s·()（）/]+', name) if len(w) >= 2] + list(aliases or [])
    return '|'.join(sorted({re.escape(x) for x in toks if x}, key=len, reverse=True))

PROG_ALIAS = {g['id']: _alias_re(g['name'], g.get('aliases')) for g in KB.pricing['programs']}
MEAL_ALIAS = {'breakfast': r'조식|아침', 'lunch': r'중식|점심', 'dinner': r'석식|저녁'}
NONE_RE = r'없|안\s*함|필요\s*없|불필요|아니|패스|skip'
YES_RE = r'^(네|예|응|그래|좋아요?|좋습니다|맞아요?|부탁|상담|요청|연결|그렇게|ㅇㅋ|ok)'

def _today():
    return datetime.date.today()

# ---------------- 파서 ----------------
def parse_date(text):
    t = text or ''
    today = _today()
    def mk(m, d):
        y = today.year
        try:
            dt = datetime.date(y, m, d)
        except ValueError:
            return None
        if dt < today - datetime.timedelta(days=1):
            dt = datetime.date(y + 1, m, d)
        return dt
    m = re.search(r'(\d{1,2})\s*월\s*(\d{1,2})\s*일?\s*(?:[~\-–]|부터)\s*(?:(\d{1,2})\s*월)?\s*(\d{1,2})\s*일?', t)
    if m:
        m1, d1 = int(m.group(1)), int(m.group(2))
        m2 = int(m.group(3)) if m.group(3) else m1
        d2 = int(m.group(4))
        s = mk(m1, d1); e = mk(m2, d2)
        if s and e:
            if e < s:
                e = datetime.date(e.year + 1, e.month, e.day)
            return {'start': s, 'nights': (e - s).days, 'month': m1}
    m = re.search(r'(\d{1,2})\s*월\s*(\d{1,2})\s*일', t) or re.search(r'(\d{1,2})\s*/\s*(\d{1,2})(?!\d)', t)
    if m and 1 <= int(m.group(1)) <= 12 and 1 <= int(m.group(2)) <= 31:
        s = mk(int(m.group(1)), int(m.group(2)))
        if s:
            return {'start': s, 'nights': None, 'month': s.month}
    m = re.search(r'(\d{1,2})\s*월', t)
    if m and 1 <= int(m.group(1)) <= 12:
        return {'start': None, 'nights': None, 'month': int(m.group(1))}
    return None

def parse_stay(text):
    t = text or ''
    if re.search(r'당일|숙박\s*(없|안|필요\s*없)', t):
        return 0
    m = re.search(r'(\d)\s*박', t)
    if m:
        return int(m.group(1))
    m = re.search(r'(\d)\s*일\s*간?$', t.strip())
    return None

def parse_pax(text, bare=False):
    m = re.search(r'(\d{1,4})\s*(명|인|분|사람)', text or '')
    if not m and bare:
        m = re.search(r'(\d{1,4})', text or '')
    return int(m.group(1)) if m else None

def parse_age(text):
    t = text or ''
    for a in AGES:
        if a in t:
            return a
    if re.search(r'초등|중학|고등|학생|청소년|어린이|유치원|아이', t): return AGES[0]
    if re.search(r'20대|30대|청년|신입|MZ', t): return AGES[1]
    if re.search(r'40대|50대|중장년|직장인|회사|직원', t): return AGES[2]
    if re.search(r'60대|70대|어르신|노인|시니어|고령', t): return AGES[3]
    if re.search(r'혼합|다양|섞|상관', t): return AGES[4]
    return None

def parse_multi(text, alias):
    t = text or ''
    if re.search(NONE_RE, t) and not any(re.search(p, t) for p in alias.values()):
        return []
    got = [k for k, p in alias.items() if re.search(p, t)]
    return got or None

def parse_hall(text):
    """대관 선택 해석: 시설명(괄호·공백 단위 토큰)이 가장 많이 일치하는 시설, 반일/종일 언급으로 동점 해소."""
    t = text or ''
    if re.search(NONE_RE, t) and not any(w in t for h in KB.pricing['halls'] for w in re.split(r'[\s()（）]+', h['name']) if len(w) >= 2):
        return 'none'
    for h in KB.pricing['halls']:
        if h['name'] in t: return h['id']  # 선택 버튼의 정확한 이름
    best, best_sc = None, 0
    for h in KB.pricing['halls']:
        toks = [w for w in re.split(r'[\s()（）]+', h['name']) if len(w) >= 2 and not re.fullmatch(r'\d+[인명]', w)]
        sc = sum(1 for w in toks if w in t) + (1 if any(a in t for a in h.get('aliases', [])) else 0)
        if re.search(r'반일|오전|오후', t) and '반일' in h['name']: sc += 0.5
        if re.search(r'종일|하루|전일', t) and '종일' in h['name']: sc += 0.5
        if sc > best_sc: best, best_sc = h, sc
    return best['id'] if best and best_sc >= 1 else None

# ---------------- 세션 ----------------
SESSION_MAX = 5000
SESSION_TTL = 6 * 3600

def _gc():
    import time
    now = time.time()
    for k in [k for k, v in SESSIONS.items() if now - v.get('_t', now) > SESSION_TTL]:
        SESSIONS.pop(k, None)
    while len(SESSIONS) > SESSION_MAX:
        SESSIONS.pop(next(iter(SESSIONS)), None)

def get_session(sid):
    import time
    with _slock:
        if len(SESSIONS) > SESSION_MAX * 0.9:
            _gc()
        if sid in SESSIONS:
            SESSIONS[sid]['_t'] = time.time()
        if not sid or sid not in SESSIONS:
            sid = uuid.uuid4().hex[:12]
            SESSIONS[sid] = {'sid': sid, 'mode': None, 'slots': {}, 'step': None, 'answered': {}, 'last_q': None, 'last_answer': None,
                             'protect': False, 'quote': None, 'ctx': {}, 'return_quote': False, 'inquiry_ids': [], 'history': [], '_t': time.time()}
        return SESSIONS[sid]

def _opt(label, value=None):
    return {'label': label, 'value': value if value is not None else label}

HOME_CHIPS = [_opt('숙박요금', '객실 요금이 얼마인가요?'), _opt('프로그램', '어떤 프로그램이 있나요?'), _opt('단체예약', 'act:group'),
              _opt('식사', '식사 가격이 어떻게 되나요?'), _opt('대관', '세미나실 대관 가능한가요?'), _opt('교통', '오시는 길 알려주세요'),
              _opt('이용방법', '예약은 어떻게 하나요?'), _opt('감면 기준', 'act:discount'), _opt('주변 관광 추천', 'act:tour'), _opt('민원·불편사항', '불편사항 접수하고 싶어요')]
TOUR_RE = re.compile(r'(관광|여행\s*(코스|일정|지)|가볼\s*(만|곳)|볼거리|명소|맛집|놀거리|데이트\s*코스|주변\s*(에\s*)?(갈|가볼|구경|관광)|(영주|예천|소백산|부석사|선비촌|무섬|회룡포).{0,10}(일정|코스|추천|갈\s*만|가볼))')


def _msg(text, sources=None, kind='text', photos=None, gen=None):
    return {'text': text, 'sources': sources or [], 'kind': kind, 'photos': photos or [], 'gen': gen}

def _resp(s, messages, options=None, multi=False, form=None, quote=None, feedback=False, mode=None, meta=None, picker=None):
    return {'sid': s['sid'], 'messages': messages,
            'ui': {'options': options or [], 'multi': multi, 'picker': picker, 'form': form, 'quote': quote, 'feedback': feedback, 'mode': mode or s['mode'], 'meta': meta or {}}}

# ---------------- 단체예약 ----------------
def _slots_summary(sl):
    p = []
    if sl.get('start'):
        d = sl['start']; p.append('{}월 {}일({})'.format(d.month, d.day, quotelib.WD[d.weekday()]))
    elif sl.get('month'):
        p.append('{}월 중(일자 미정)'.format(sl['month']))
    if sl.get('nights') is not None:
        p.append('당일' if sl['nights'] == 0 else '{}박 {}일'.format(sl['nights'], sl['nights'] + 1))
    if sl.get('pax'): p.append('{}명'.format(sl['pax']))
    if sl.get('age'): p.append(sl['age'])
    return ' · '.join(p)

MEAL_ORDER = ['breakfast', 'lunch', 'dinner']

def _meal_options_for_day(day, days):
    """일차별 선택 가능한 식사. 첫날은 중식·석식, 그 외는 조식·중식·석식."""
    if day == 1:
        return ['lunch', 'dinner']
    return list(MEAL_ORDER)

def _meal_plan_text(sl):
    mp = sl.get('meal_plan')
    if not mp:
        return ''
    nm = {m['id']: m['name'] for m in KB.pricing['meals']}
    parts = []
    for d in sorted(mp, key=lambda x: int(x)):
        if mp[d]:
            parts.append('{}일차 {}'.format(d, '·'.join(nm.get(i, i) for i in mp[d])))
    return ' / '.join(parts)

def _hall_plan_text(sl):
    hs = sl.get('halls')
    if not hs:
        return ''
    nm = {h['id']: h['name'] for h in KB.pricing['halls']}
    return ' / '.join('{} {}일차 {}~{}({}시간)'.format(nm.get(b['id'], b['id']), b['day'], b['start'], _end_time(b['start'], b['hours']), b['hours']) for b in hs)

def _end_time(start, hours):
    m = quotelib._t2m(start) or 0
    return quotelib._hm(min(m + int(hours) * 60, 24 * 60))

def _parse_meal_plan(t, days):
    import json as _j
    try:
        raw = _j.loads(t[len('mealplan:'):] or '{}')
    except ValueError:
        return None
    ok = {m['id'] for m in KB.pricing['meals']}
    plan = {}
    for k, v in (raw or {}).items():
        try:
            d = int(k)
        except ValueError:
            return None
        if not (1 <= d <= days) or not isinstance(v, list):
            return None
        got = [i for i in MEAL_ORDER if i in v and i in ok and i in _meal_options_for_day(d, days)]
        if got: plan[d] = got
    return plan

def _parse_hall_plan(t, days):
    """(대관 목록, 오류문). 시설ID·일차·시작시각·이용시간을 검증한다."""
    import json as _j
    try:
        raw = _j.loads(t[len('hallplan:'):] or '[]')
    except ValueError:
        return None, '대관 선택 내용을 읽지 못했습니다.'
    ids = {h['id']: h for h in KB.pricing['halls']}
    out = []
    for b in raw if isinstance(raw, list) else []:
        h = ids.get(b.get('id'))
        try:
            day, hrs = int(b.get('day')), int(b.get('hours'))
        except (TypeError, ValueError):
            return None, '대관 일차·이용 시간을 확인해 주세요.'
        st = quotelib._t2m(b.get('start'))
        if not h or not (1 <= day <= days) or st is None or not (1 <= hrs <= 12):
            return None, '대관 선택(시설·일차·시작 시각·이용 시간)을 확인해 주세요.'
        if st < quotelib.HALL_OPEN or st + hrs * 60 > quotelib.HALL_CLOSE:
            return None, '{} 이용 시간이 운영시간(09:00~21:00)을 벗어납니다. 시작 시각이나 이용 시간을 조정해 주세요.'.format(h['name'])
        out.append({'id': h['id'], 'day': day, 'start': quotelib._hm(st), 'hours': max(hrs, 1)})
    return out, None

def _picker_rooms(pax=0):
    P = KB.pricing
    two = any(r.get('price_peak') for r in P['rooms'])
    if two:
        head = ['객실', '구성', '정원', '비수기 주중', '성수기·주말']
        rows = [{'value': r['name'], 'capacity': r['capacity'], 'cells': [r['name'], r.get('detail') or '', '{}명'.format(r['capacity']), won(r['price']), won(r.get('price_peak') or r['price'])]} for r in P['rooms']]
    else:
        head = ['객실', '정원', '1박 요금']
        rows = [{'value': r['name'], 'capacity': r['capacity'], 'cells': [r['name'], '{}명'.format(r['capacity']), won(r['price'])]} for r in P['rooms']]
    return {'type': 'rooms', 'pax': int(pax or 0), 'head': head, 'rows': rows}

def _picker_programs():
    P = KB.pricing
    return {'type': 'select', 'head': ['프로그램', '시간', '1인 요금'],
            'rows': [{'value': g['name'], 'cells': [g['name'], '{}분'.format(g['minutes']), won(g['price'])]} for g in P['programs']],
            'none': {'label': '프로그램 없음', 'value': '프로그램 없음'}}

def _picker_kids(pax):
    mt = {t['id']: t for t in (KB.pricing.get('meal_tiers') or [])}
    def pr(k): return '무료' if mt[k]['price'] == 0 else won(mt[k]['price'])
    rows = [{'id': 'child', 'name': '어린이', 'sub': '{} · 1식 {}'.format(mt['child']['basis'], pr('child'))},
            {'id': 'infant_with', 'name': '영·유아(보호자 동반)', 'sub': '{} · 1식 {}'.format(mt['infant_with']['basis'], pr('infant_with'))},
            {'id': 'infant_without', 'name': '영·유아(보호자 미동반)', 'sub': '{} · 1식 {}'.format(mt['infant_without']['basis'], pr('infant_without'))}]
    return {'type': 'kids', 'pax': int(pax or 0), 'rows': rows, 'none': {'label': '해당 없음(모두 만 13세 이상)', 'value': '어린이·영유아 없음'}}

def _picker_halls(days):
    P = KB.pricing
    extra = any(h.get('extra') for h in P['halls'])
    return {'type': 'hall', 'days': days, 'open': '09:00', 'close': '21:00',
            'head': ['시설', '수용', '기본 2시간'] + (['추가 1시간당'] if extra else []),
            'rows': [{'value': h['id'], 'name': h['name'], 'cells': [h['name'], '{}명'.format(h['capacity']), won(h['price'])] + ([won(h['extra']) if h.get('extra') else '-'] if extra else [])} for h in P['halls']],
            'none': {'label': '대관 필요 없음', 'value': '대관 필요 없음'}}

def _picker_meals(nights):
    days = nights + 1
    nm = {m['id']: m['name'] for m in KB.pricing['meals']}
    return {'type': 'meal', 'none': {'label': '식사 안 함', 'value': '식사 안 함'},
            'days': [{'day': d, 'label': '당일' if nights == 0 else '{}일차'.format(d), 'meals': [{'id': i, 'name': nm.get(i, i)} for i in _meal_options_for_day(d, days) if i in nm]} for d in range(1, days + 1)]}

def _next_step(sl):
    for st in STEPS:
        if st == 'date' and (sl.get('start') or sl.get('date_skip')): continue
        if st == 'stay' and sl.get('nights') is not None: continue
        if st == 'pax' and sl.get('pax'): continue
        if st == 'age' and sl.get('age'): continue
        if st == 'room' and (sl.get('nights') == 0 or sl.get('room_done')): continue
        if st == 'program' and 'programs' in sl: continue
        if st == 'meal' and 'meals' in sl: continue
        if st == 'kids' and (not KB.pricing.get('meal_tiers') or 'kids' in sl or not sl.get('meals')): continue
        if st == 'hall' and ('hall' in sl or 'halls' in sl): continue
        if st == 'notes' and 'notes' in sl: continue
        return st
    return None

def _ask(s, step):
    sl = s['slots']
    act = [x for x in STEPS if not (x == 'kids' and not KB.pricing.get('meal_tiers'))]
    n = act.index(step) + 1
    head = '({}/{}) '.format(n, len(act))
    P = KB.pricing
    if step == 'date':
        hint = '{}월 중으로 말씀하셨어요. 정확한 날짜가 정해졌다면 '.format(sl['month']) if sl.get('month') else ''
        return _resp(s, [_msg(head + hint + '희망 이용일을 알려 주세요. 예) 11월 20일~21일')], [_opt('아직 미정', '일자 미정')])
    if step == 'stay':
        return _resp(s, [_msg(head + '당일 일정인가요, 숙박이 필요하신가요?')], [_opt(x) for x in STAYS])
    if step == 'pax':
        return _resp(s, [_msg(head + '총 인원은 몇 명인가요? 예) 40명')])
    if step == 'age':
        return _resp(s, [_msg(head + '주요 연령대를 선택해 주세요(여러 개 선택 가능).')], [_opt(x) for x in AGES[:4]], multi=True)
    if step == 'room':
        rec = quotelib.pick_room(P, int(sl.get('pax') or 10), None, sl.get('start'), sl.get('nights') or 1)
        return _resp(s, [_msg(head + '객실 유형과 객실 수를 선택해 주세요. 유형을 섞어서 고르셔도 됩니다. 정원 합계가 인원 {}명 이상이 되도록 골라 주세요. (참고: 총 객실비가 가장 낮은 유형은 {})'.format(sl.get('pax') or '', rec['name']))], picker=_picker_rooms(sl.get('pax')))
    if step == 'program':
        return _resp(s, [_msg(head + '희망하시는 프로그램을 표에서 체크해 주세요(여러 개 선택 가능). 객실 이용 시 프로그램은 1개 이상 필요합니다.')], picker=_picker_programs())
    if step == 'meal':
        n = sl.get('nights') or 0
        return _resp(s, [_msg(head + '식사는 어떻게 하실까요? {}별로 원하는 식사를 눌러 선택해 주세요(복수 선택 가능).'.format('당일' if n == 0 else '일차'))], picker=_picker_meals(n))
    if step == 'kids':
        mt = {t['id']: t for t in (KB.pricing.get('meal_tiers') or [])}
        return _resp(s, [_msg(head + '식사 이용료는 연령에 따라 다릅니다. 성인(만 13세 이상) {}, 어린이(36개월 이상 만 13세 미만) {}, 영·유아(36개월 미만)는 보호자 동반 시 무료·미동반 시 {}입니다. 전체 {}명 중 어린이·영·유아가 있으면 인원을 입력해 주세요. 나이는 생년월일 확인 서류로 확인합니다.'.format(won(mt['adult']['price']), won(mt['child']['price']), won(mt['infant_without']['price']), sl.get('pax') or ''))], picker=_picker_kids(sl.get('pax')))
    if step == 'hall':
        n = sl.get('nights') or 0
        return _resp(s, [_msg(head + '교육·회의용 대관이 필요하신가요? 시설을 체크하고 이용 일차·시작 시각·이용 시간을 고르세요(시설은 여러 곳 선택 가능). 기본 2시간 요금에 추가 1시간당 요금이 더해집니다. 이용 가능 시간은 09:00~21:00입니다.')], picker=_picker_halls(n + 1))
    if step == 'notes':
        return _resp(s, [_msg(head + '그 밖에 요청사항이 있으면 적어 주세요. (예: 대형버스 주차, 휠체어 이용자 포함)')], [_opt('없음')])

def nights_room(sl):
    return (sl.get('nights') or 0) > 0

def _quote_opts(s):
    o = [_opt('이 조건으로 상담 요청하기', 'act:consult'), _opt('조건 수정하기', 'act:modify'), _opt('이메일로 받기', 'act:email')]
    if nights_room(s['slots']): o.append(_opt('감면 대상 확인·예상 감면액', 'act:discount'))
    return o + [_opt('취소 시 위약금 안내', 'act:penalty'), _opt('주변 관광 일정도 추천받기', 'act:tour')]

def _discount_msg(with_hint=False):
    red = KB.pricing.get('reduction') or []
    if not red: return None
    td = KB.table_data()['{DISCOUNT_TABLE}']
    txt = '감면 대상(객실 이용료만 해당, 증빙서류 지참 필수, 감면은 중복 적용되지 않고 가장 높은 하나만 적용)'
    m = _msg(txt, [{'title': '감면 기준표(브로슈어)', 'as_of': KB.pricing['as_of']}])
    m['blocks'] = [{'type': 'text', 'text': txt, 'strong': True}] + td + ([{'type': 'text', 'text': '아래 \'감면 대상 확인·예상 감면액\' 버튼을 누르면 해당하시는 대상의 예상 감면액을 볼 수 있습니다.', 'muted': True}] if with_hint else [])
    return m

def _discount_estimate(s, name):
    red = {x['name']: x for x in (KB.pricing.get('reduction') or [])}
    x = red.get(name); q = s.get('quote')
    if not x or not q: return None
    lines = ['{} — {}'.format(x['name'], x['basis']), '감면율: 비수기 주중 {:g}% / 성수기·주말 {:g}%'.format(x['rate_off'], x['rate_peak']), '증빙: {}'.format(x['proof'])]
    best = 0
    for u in q.get('room_unit') or []:
        v = int(round(u['off'] * x['rate_off'] / 100.0 + u['peak'] * x['rate_peak'] / 100.0))
        best = max(best, v)
        lines.append('· {} 1실 기준 예상 감면액 {}'.format(u['name'], won(v)))
    lines.append('※ 감면은 후할인 방식으로 입실 시 증빙 확인 후 객실 이용료에서 부분취소(환불)되며, 1가정(1인)당 1실에만 적용됩니다. 대상자가 여러 명이면 객실별로 각각 적용 여부를 담당자가 확인합니다. 예상 금액이며 최종 금액은 담당자 확인이 필요합니다.')
    return '\n'.join(lines)

def _quote_response(s):
    sl = s['slots']
    hall = None if sl.get('hall') in (None, 'none') else sl['hall']
    q = quotelib.build(KB.pricing, {'start': sl.get('start'), 'nights': sl.get('nights', 0), 'pax': sl['pax'], 'room': sl.get('room'), 'rooms': sl.get('rooms'), 'room_counts': sl.get('room_counts'),
                                    'programs': sl.get('programs', []), 'meals': sl.get('meals', []), 'meal_plan': sl.get('meal_plan'), 'kids': sl.get('kids'), 'first_lunch': sl.get('first_lunch'),
                                    'hall': hall, 'halls': sl.get('halls')})
    s['quote'] = q
    s['mode'] = 'group_quote'
    s['last_answer'] = quotelib.quote_text(q)
    intro = '입력하신 조건으로 예시 일정표와 예상 견적을 만들었습니다.'
    if q['warnings']:
        intro += '\n⚠ ' + '\n⚠ '.join(q['warnings'])
    msg = _msg(intro, [{'title': '단가: 요금표(모의데이터)', 'as_of': KB.pricing['as_of']}])
    opts = _quote_opts(s)
    msgs = [msg]
    dm = _discount_msg(with_hint=True) if nights_room(sl) else None
    if dm: msgs.append(dm)
    return _resp(s, msgs, opts, quote={'schedule': q['schedule'], 'lines': q['lines'], 'total_text': q['total_text'],
                                         'per_person_text': q['per_person_text'], 'disclaimer': q['disclaimer'], 'summary': _slots_summary(sl),
                                         'notes': sl.get('notes') or ''}, mode='group_quote')

def _llm_fill(s, text, only_missing=True):
    """LLM으로 단체 조건을 추출해 비어 있는 항목만 채운다(검증된 값만). 변경이 있으면 True."""
    if not llm.enabled():
        return False
    P = KB.pricing
    ex = llm.extract_group(text, {'ages': AGES, 'programs': {x['id']: x['name'] for x in P['programs']},
                                  'meals': {x['id']: x['name'] for x in P['meals']}, 'halls': {x['id']: x['name'] for x in P['halls']}})
    sl, changed = s['slots'], False
    def put(k, v):
        nonlocal changed
        if v is None or (only_missing and k in sl):
            return
        sl[k] = v; changed = True
    if 'start' in ex and not sl.get('start'):
        sl['start'] = ex['start']; sl['month'] = ex['start'].month; changed = True
    if 'nights' in ex and sl.get('nights') is None: sl['nights'] = ex['nights']; changed = True
    if 'pax' in ex and not sl.get('pax'): sl['pax'] = ex['pax']; changed = True
    if 'age' in ex and not sl.get('age'): sl['age'] = ex['age']; changed = True
    if 'programs' in ex and 'programs' not in sl: put('programs', ex['programs'])
    if 'meals' in ex and 'meals' not in sl: put('meals', ex['meals'])
    if 'hall' in ex and 'hall' not in sl: put('hall', ex['hall'])
    return changed

def _start_group(s, text):
    s['mode'] = 'group'; s['slots'] = {}; s['quote'] = None; s['return_quote'] = False
    sl = s['slots']
    d = parse_date(text)
    if d:
        sl['start'] = d['start']; sl['month'] = d['month']
        if d['nights'] is not None: sl['nights'] = d['nights']
    st = parse_stay(text)
    if st is not None: sl['nights'] = st
    px = parse_pax(text)
    if px: sl['pax'] = px
    ag = parse_age(text)
    if ag and re.search(r'학생|청소년|초등|중학|고등|유치원|어르신|60대|70대|20대|30대|40대|50대', text): sl['age'] = ag
    pr = [k for k, p in PROG_ALIAS.items() if re.search(p, text)]
    if pr: sl['programs'] = pr
    ml = [k for k, p in MEAL_ALIAS.items() if re.search(p, text)]
    if ml:
        sl['meals'] = ml
        if re.search(r'첫\s*날.{0,3}(점심|중식)', text): sl['first_lunch'] = True
    h = parse_hall(text) if text else None
    if h == 'none': h = None
    if h: sl['hall'] = h
    if text:
        _llm_fill(s, text)
    got = _slots_summary(sl)
    intro = '단체 이용 상담을 도와드리겠습니다. 몇 가지만 여쭤보고 예시 일정표와 예상 견적을 만들어 드릴게요.'
    if got:
        intro += '\n말씀해 주신 내용: ' + got
    nxt = _next_step(sl)
    s['step'] = nxt
    r = _ask(s, nxt)
    r['messages'].insert(0, _msg(intro, [{'title': '단체 이용 안내(모의)', 'as_of': '모의데이터'}]))
    return r

def _fill_step(s, text):
    """현재 step 응답 파싱. 성공 True / 실패 False."""
    sl, st = s['slots'], s['step']
    t = text.strip()
    if st == 'date':
        if re.search(r'미정|모르|아직', t):
            sl['date_skip'] = True; return True
        d = parse_date(t)
        if not d: return False
        sl['start'] = d['start']; sl['month'] = d['month']
        if d['nights'] is not None: sl['nights'] = d['nights']
        return True
    if st == 'stay':
        n = parse_stay(t)
        if n is None: return False
        sl['nights'] = n; return True
    if st == 'pax':
        n = parse_pax(t, bare=True)
        if not n or n < 1 or n > 1000: return False
        sl['pax'] = n; return True
    if st == 'age':
        got = [a for a in AGES if a in t]
        if got:
            sl['age'] = ', '.join(got); return True
        a = parse_age(t)
        if not a: return False
        sl['age'] = a; return True
    if st == 'room':
        if t.startswith('roomplan:'):
            try:
                raw = json.loads(t[len('roomplan:'):] or '{}')
            except ValueError:
                return False
            ok = {r['name'] for r in KB.pricing['rooms']}
            cnt = {}
            for k, v in (raw or {}).items():
                try: v = int(v)
                except (TypeError, ValueError): return False
                if k in ok and 0 < v <= 200: cnt[k] = v
            if not cnt: return False
            sl['room_counts'] = cnt; sl['rooms'] = list(cnt); sl['room'] = next(iter(cnt)) if len(cnt) == 1 else None; sl['room_done'] = True; return True
        if re.search(r'추천|상관|아무|알아서', t):
            sl['room'] = None; sl['rooms'] = []; sl.pop('room_counts', None); sl['room_done'] = True; return True
        picked = [r['name'] for r in KB.pricing['rooms'] if r['name'] in t or r['name'].split('(')[0] in t or re.search(r'(?<![A-Za-z])%s(?![A-Za-z])' % re.escape(r['id']), t)]
        if not picked: return False
        sl['rooms'] = picked; sl['room'] = picked[0] if len(picked) == 1 else None; sl['room_done'] = True; return True
    if st == 'program':
        v = parse_multi(t, PROG_ALIAS)
        if v is None: return False
        sl['programs'] = v; return True
    if st == 'meal' and t.startswith('mealplan:'):
        plan = _parse_meal_plan(t, (sl.get('nights') or 0) + 1)
        if plan is None: return False
        sl['meal_plan'] = plan; sl['meals'] = [i for i in MEAL_ORDER if any(i in v for v in plan.values())]; sl['first_lunch'] = False
        return True
    if st == 'meal':
        sl.pop('meal_plan', None)
        v = parse_multi(t, MEAL_ALIAS)
        if v is None: return False
        sl['meals'] = v
        fl = bool(re.search(r'첫\s*날|도착.{0,4}(점심|중식)', t))
        if fl and 'lunch' not in v: v.append('lunch')
        sl['first_lunch'] = fl; return True
    if st == 'kids':
        if re.search(r'없음|해당\s*없|모두\s*(성인|13)', t) and 'kids:' not in t:
            sl['kids'] = {}; return True
        raw = {}
        if t.startswith('kids:'):
            try: raw = json.loads(t[5:] or '{}')
            except ValueError: return False
        else:
            for key, pat in (('infant_without', r'미동반\D{0,6}(\d+)|(?:영유아|영·유아|유아|영아)\D{0,10}미동반\D{0,4}(\d+)'), ('infant_with', r'(?:영유아|영·유아|유아|영아)\D{0,10}(?:동반|보호자)\D{0,4}(\d+)'), ('child', r'어린이\D{0,4}(\d+)')):
                m = re.search(pat, t)
                if m: raw[key] = next(g for g in m.groups() if g)
        out = {}
        for k in ('child', 'infant_with', 'infant_without'):
            try: v = int(raw.get(k) or 0)
            except (TypeError, ValueError): return False
            if v < 0 or v > int(sl.get('pax') or 0): return False
            if v: out[k] = v
        if not out and not t.startswith('kids:'): return False
        if sum(out.values()) > int(sl.get('pax') or 0): return False
        sl['kids'] = out; return True
    if st == 'hall' and t.startswith('hallplan:'):
        halls, err = _parse_hall_plan(t, (sl.get('nights') or 0) + 1)
        if halls is None:
            s['_err'] = err; return False
        sl['halls'] = halls; sl['hall'] = halls[0]['id'] if halls else 'none'
        return True
    if st == 'hall':
        h = parse_hall(t)
        if not h: return False
        sl['hall'] = h; sl.pop('halls', None)
        if h == 'none': sl['halls'] = []
        return True
    if st == 'notes':
        sl['notes'] = '' if re.fullmatch(r'\s*(없음|없어요|없습니다|없다|x|X)\s*', t) else t[:300]; return True
    return False

def _group_turn(s, text):
    if re.search(r'처음부터|다시\s*시작|그만|취소할게|중단', text):
        s['mode'] = None; s['slots'] = {}; s['step'] = None
        return _resp(s, [_msg('단체 상담을 중단했습니다. 다른 궁금한 점을 입력해 주세요.')], HOME_CHIPS)
    if s['step'] and _fill_step(s, text):
        nxt = _next_step(s['slots'])
        if nxt and not s['return_quote']:
            s['step'] = nxt
            return _ask(s, nxt)
        if nxt and s['return_quote']:     # 수정 중 새로 필요한 항목(예: 박수 변경 -> 객실)
            s['step'] = nxt
            return _ask(s, nxt)
        s['step'] = None
        return _quote_response(s)
    # 파싱 실패: LLM이 있으면 문장에서 조건 추출을 한 번 더 시도
    if llm.enabled() and _llm_fill(s, text):
        nxt = _next_step(s['slots'])
        if nxt:
            s['step'] = nxt
            r = _ask(s, nxt)
            r['messages'].insert(0, _msg('말씀하신 내용에서 조건을 읽어 반영했습니다: ' + _slots_summary(s['slots'])))
            return r
        s['step'] = None
        return _quote_response(s)
    # 일반 질문이면 근거 답변 후 이어가기
    top = KB.search(text, 1)[0]
    if top[0] >= KB.STRONG and top[1]['kind'] != 'group':
        ans = _answer_message(s, top[1], text)
        r = _ask(s, s['step'])
        r['messages'] = [ans, _msg('단체 상담을 이어서 진행할게요.')] + r['messages']
        return r
    r = _ask(s, s['step'])
    r['messages'].insert(0, _msg(s.pop('_err', None) or '입력하신 내용을 이해하지 못했어요. 아래 안내에 맞춰 다시 입력하거나 버튼을 눌러 주세요.'))
    return r

# ---------------- 일반 답변 ----------------
def _photos(entries):
    out, seen = [], set()
    for e in entries:
        for ph in e.get('photos') or []:
            if ph not in seen:
                seen.add(ph); out.append({'src': '/img/' + ph, 'caption': e['title']})
    return out[:3]

def _answer_message(s, e, question, text=None, gen=None, entries=None):
    body = text if text is not None else KB.render(e)
    cnt = s['answered'].get(e['id'], 0)
    s['answered'][e['id']] = cnt + 1
    pre = '앞서 안내드린 내용과 같은 문의입니다. 다시 안내드립니다.\n' if cnt >= 1 else ''
    ents = entries or [e]
    if any(x.get('realtime') for x in ents):
        body += '\n\n※ 요금·운영 정보는 기준 시점 자료이며 실시간 예약 가능 여부를 의미하지 않습니다.'
    src = [{'title': x['source'], 'as_of': x['as_of'], 'mock': bool(x.get('mock'))} for x in ents]
    s['last_answer'] = body
    m = _msg(pre + body, src, photos=_photos(ents), gen=gen)
    if text is None:                      # 요금표·위약금표 등은 화면에서 표로 보여 준다(글 본문은 그대로 유지: 이메일·상담 전달용)
        blocks = KB.blocks(e)
        if blocks:
            if pre: blocks.insert(0, {'type': 'text', 'text': pre.strip()})
            if any(x.get('realtime') for x in ents): blocks.append({'type': 'text', 'text': '※ 요금·운영 정보는 기준 시점 자료이며 실시간 예약 가능 여부를 의미하지 않습니다.', 'muted': True})
            m['blocks'] = blocks
    return m

def _escalate_prompt(s, text, reason):
    s['mode'] = 'confirm_consult'
    s['last_q'] = text
    s['ctx'] = {'reason': reason}
    return _resp(s, [_msg('정확한 확인이 필요한 사항입니다. 담당자 상담을 요청하시겠습니까?\n(담당자 연락처는 공개되지 않으며, 접수하신 내용은 담당 업무로 자동 전달됩니다.)')],
                 [_opt('상담 요청하기', 'act:consult'), _opt('다른 질문하기', 'act:reset')])

def _consult_form(s, question, cat, dept, ai_answer, needs):
    s['mode'] = 'consult'
    s['ctx'] = {'question': question, 'category': cat, 'dept': dept, 'ai_answer': ai_answer, 'needs_check': needs}
    form = {'type': 'consult', 'kind': 'consult', 'category': cat, 'dept_name': KB.dept_name(dept), 'summary': question[:300]}
    msg = _msg('상담 내용을 아래와 같이 정리했습니다. 담당 업무: {} / 분류: {}\n희망하시는 연락 방법과 시간을 선택해 주세요. 요청하신 시간에 최대한 맞춰 연락드리며, 어려운 경우 담당자가 가능한 일정을 안내드립니다.'.format(KB.dept_name(dept), cat))
    return _resp(s, [msg], form=form)

CONSULT_RE = re.compile(r'(담당자|직원|사람).{0,12}(통화|이야기|말씀|연락|상담|얘기|만나)|상담.{0,6}(원|하고\s*싶|요청|받고)|항의|민원.{0,6}(접수|넣|제기|신청)|연락.{0,4}(주세요|받고|부탁)|통화하고|불편사항\s*접수|건의')
GROUP_RE = re.compile(r'단체.{0,10}(일정표|견적)|(일정표|견적).{0,8}단체|단체.{0,10}(가려|가고|예약|이용하고|방문하려|오려|숙박|상담|문의)|(워크숍|워크샵|단체연수|MT|엠티|세미나|동호회|체험학습).{0,10}(가려|하고\s*싶|예약|가고|하려|계획)')
HIGH_RE = re.compile(r'(가려|가고|가요|갈\s*예정|방문|오려|이용|숙박|예약|묵|워크숍|연수|행사|체험)')

_LIVE_RE = re.compile(r'남아\s*있|잔여|빈\s*객실|예약\s*번호|예약\s*상태|예약\s*현황|오늘.{0,6}날씨|내일.{0,6}날씨|주식|코인|투자')

PEN_RE = re.compile(r'(위약금|취소\s*수수료|공제|환불|환급|취소).{0,14}(얼마|계산|발생|없|언제|며칠|몇\s*일|기한|까지|가능)|(며칠|몇\s*일|언제).{0,10}(취소|전)|취소.{0,6}(하면|시|할\s*경우|하려|해야)')

def _parse_amounts(text):
    """'30만원', '120,000원' -> (시설·프로그램 금액, 식사 금액). 식사 앞에서 언급되면 식사 금액."""
    fac = meal = None
    for m in re.finditer(r'(\d[\d,]*)\s*(만)?\s*원', text or ''):
        v = int(m.group(1).replace(',', '')) * (10000 if m.group(2) else 1)
        if re.search(r'식사|식대|조식|중식|석식', (text[max(0, m.start() - 8):m.start()])): meal = v
        else: fac = v
    return fac, meal

def _penalty(s, use_date, text=''):
    fac, meal = _parse_amounts(text)
    out, err, blocks = penlib.explain_full(KB.pricing, use_date, _today(), fac, meal)
    store.log_turn(s['sid'], 'answer', 'penalty_calc', '위약금 계산', 1.0, 1 if out else 0, '예약', mode='template')
    if err:
        return _resp(s, [_msg(err)], [_opt('다른 질문하기', 'act:reset')])
    s['mode'] = 'penalty_wait'      # 다른 날짜·금액으로 이어서 다시 계산할 수 있게 유지
    out += '\n\n※ 이 안내는 등록된 위약금 기준표로 계산한 참고용입니다. 여러 날 이용·일부 취소·재난 등 예외는 담당자 확인이 필요하며, 최종 금액은 예약 시스템에서 확정됩니다.'
    opts = [_opt('위약금 규정 전체 보기', 'kb:refund'), _opt('담당자 상담 요청', 'act:consult'), _opt('다른 질문하기', 'act:reset')]
    s['last_answer'] = out
    m = _msg(out, [{'title': '위약금 공제 및 배상기준', 'as_of': KB.pricing.get('as_of', '')}])
    m['blocks'] = blocks + [{'type': 'text', 'text': out.rsplit('\n\n※', 1)[-1] and '※ ' + out.rsplit('※ ', 1)[-1], 'muted': True}]
    return _resp(s, [m], opts, meta={'mode': 'penalty'})

def _ask_penalty_date(s):
    s['mode'] = 'penalty_wait'
    return _resp(s, [_msg('이용(입실) 예정일을 알려 주세요. 취소 시점별 위약금을 계산해 드립니다. (예: 11월 9일) 금액을 함께 알려 주시면(예: 30만원) 공제액도 계산합니다.')],
                 [_opt('위약금 규정 전체 보기', 'kb:refund'), _opt('다른 질문하기', 'act:reset')])

def _tour_context(s):
    sl = s['slots']; q = s.get('quote')
    if not sl or not (sl.get('start') or q):
        return ''
    lines = []
    if sl.get('start'): lines.append('이용 시작일: %s, %s박' % (sl['start'], sl.get('nights', 1)))
    if sl.get('pax'): lines.append('인원: %s명 (단체 이동은 대형버스 가능성)' % sl['pax'])
    if sl.get('age'): lines.append('연령대: %s' % sl['age'])
    if q:
        for d in q.get('schedule', []):
            lines.append('%s일차(%s) 치유원 일정: ' % (d['day'], d.get('date', '')) + ' / '.join('%s %s' % (i['time'], i['title']) for i in d['items']))
    return '\n'.join(lines)

def _tour(s, text=''):
    ctx = _tour_context(s)
    out = llm.tour_plan(ctx, text if text and not text.startswith('act:') else '')
    store.log_turn(s['sid'], 'tour', 'tour', '주변 관광 일정', 1.0, 1 if out else 0, '관광', mode='llm' if out else 'none')
    opts = [_opt('다른 질문하기', 'act:reset')]
    if s.get('quote'): opts.insert(0, _opt('상담 요청하기', 'act:consult'))
    if not out:
        return _resp(s, [_msg('주변 관광 일정 추천은 AI 연동이 켜져 있어야 이용할 수 있습니다. 지금은 연결되어 있지 않거나 응답이 늦어 만들지 못했습니다. '
                              '영주·예천 관광 정보는 각 시·군 관광 누리집을 확인해 주세요.')], opts)
    note = '\n\n※ AI가 일반 지식(및 검색)으로 만든 참고용 추천입니다. 치유원의 공식 안내가 아니며 운영시간·요금·휴무는 방문 전에 확인해 주세요.'
    return _resp(s, [_msg(out + note, gen='tour')], opts)

def handle(sid, text, label=None):
    s = get_session(sid)
    text = (text or '').strip()
    text = text[:4000] if text.startswith(('mealplan:', 'hallplan:', 'roomplan:', 'kids:')) else text[:1000]
    if not text:
        return _resp(s, [_msg('궁금한 내용을 편하게 입력해 주세요.')], HOME_CHIPS)
    store.touch_session(s['sid'], label or text)
    s['history'].append(text)
    # 보호 필요 표현(폭언·위협): 차단하지 않고 안내 + 내부 플래그
    if protect_hit(text):
        s['protect'] = True
        store.log_turn(s['sid'], 'protect', None, None, 0, 0, '민원', 'protect')
        r = _resp(s, [_msg('불편을 느끼신 마음은 충분히 이해합니다. 다만 직원 보호를 위해 폭언·위협 표현이 포함된 상담은 별도 절차로 안내될 수 있습니다. '
                           '불편하신 내용을 차분히 말씀해 주시면 담당 업무에 정중히 전달해 드리겠습니다.')],
                  [_opt('불편사항 접수하기', 'act:consult'), _opt('다른 질문하기', 'act:reset')])
        s['mode'] = 'confirm_consult'; s['last_q'] = text; s['ctx'] = {'reason': '직원 보호 필요 표현 감지'}
        return r
    # 액션
    if text.startswith('act:'):
        return _action(s, text[4:])
    if text.startswith('red:') and s.get('quote'):
        est = _discount_estimate(s, text[4:])
        if est:
            s['last_answer'] = est
            return _resp(s, [_msg(est)], [_opt('다른 감면 대상 보기', 'act:discount')] + _quote_opts(s)[:3])
    if text.startswith('mod:'):
        st = text[4:]
        if st in STEPS:
            if st == 'date': s['slots'].pop('start', None); s['slots'].pop('month', None); s['slots'].pop('date_skip', None)
            elif st == 'stay':
                for k in ('nights', 'room_done', 'meals', 'meal_plan', 'first_lunch', 'kids', 'hall', 'halls'): s['slots'].pop(k, None)    # 일수가 바뀌면 일차별 식사·대관을 다시 묻는다
            elif st == 'pax': s['slots'].pop('pax', None)
            elif st == 'age': s['slots'].pop('age', None)
            elif st == 'room':
                for k in ('room_done', 'room', 'rooms', 'room_counts'): s['slots'].pop(k, None)
            elif st == 'meal':
                for k in ('meals', 'meal_plan', 'first_lunch', 'kids'): s['slots'].pop(k, None)
            elif st == 'kids': s['slots'].pop('kids', None)
            elif st == 'hall':
                for k in ('hall', 'halls'): s['slots'].pop(k, None)
            else: s['slots'].pop({'program': 'programs', 'notes': 'notes'}[st], None)
            s['mode'] = 'group'; s['step'] = st; s['return_quote'] = True
            if st == 'room' and s['slots'].get('nights') == 0:
                return _quote_response(s)
            return _ask(s, st)
    if text.startswith('kb:'):
        e = next((x for x in KB.entries if x['id'] == text[3:]), None)
        if e:
            store.log_turn(s['sid'], 'kb_choice', e['id'], e['title'], 1.0, 1, e['category'])
            return _kb_reply(s, e, e['title'])
    # 단체 흐름 진행 중
    if s['mode'] == 'group' and s['step']:
        return _group_turn(s, text)
    if s['mode'] == 'confirm_consult' and re.search(YES_RE, text):
        return _action(s, 'consult')
    if s['mode'] == 'confirm_consult' and re.search(r'^(아니|아뇨|괜찮|됐|다른)', text):
        return _action(s, 'reset')
    # 인사/감사
    if re.fullmatch(r'\s*(안녕하세요?|안녕|하이|hello|hi|반갑습니다|처음이에요)[\s!.?]*', text, re.I):
        return _resp(s, [_msg('안녕하세요, 숲톡 민원AI입니다. 묻기만 하세요. 연결과 안내는 AI가 합니다.\n아래 버튼을 누르거나 궁금한 내용을 바로 입력해 주세요.')], HOME_CHIPS)
    if re.search(r'^(감사|고맙|고마워|땡큐|수고)', text.strip()):
        return _resp(s, [_msg('도움이 되었다니 다행입니다. 더 궁금한 점이 있으면 언제든 물어보세요.')], HOME_CHIPS)
    if s['mode'] == 'penalty_wait':
        d = parse_date(text)
        if d and d.get('start') and not GROUP_RE.search(text) and not TOUR_RE.search(text) and (len(text) <= 40 or PEN_RE.search(text) or re.search(r'이용|취소|입실', text)):
            return _penalty(s, d['start'], text)
        if not PEN_RE.search(text):
            s['mode'] = None
    if KB.pricing.get('penalty') and PEN_RE.search(text) and not GROUP_RE.search(text):
        d = parse_date(text)
        if d and d.get('start'):
            return _penalty(s, d['start'], text)
        if re.search(r'며칠|몇\s*일|언제|얼마|계산|내\s*(일정|예약)', text):
            return _ask_penalty_date(s)
    if TOUR_RE.search(text) and not GROUP_RE.search(text):
        return _tour(s, text)
    pax = parse_pax(text)
    top = KB.search(text, 3)
    use_llm = llm.enabled()
    u = llm.understand(text, s['history'][:-1]) if use_llm else None
    intent = u['intent'] if u else None
    # 단체 의도
    if GROUP_RE.search(text) or (pax and pax >= KB.rules['group_min_pax'] and HIGH_RE.search(text)) or intent == 'group':
        store.log_turn(s['sid'], 'group', 'group_info', '단체 이용 안내', top[0][0], 1, '단체', mode='llm' if u else 'rule')
        r = _start_group(s, text)
        r['ui']['meta'] = {'mode': 'group', 'llm': bool(u)}
        return r
    # 상담 요청 의도
    if CONSULT_RE.search(text) or intent == 'consult':
        cat, dept = ('민원', 'CS')
        st, e = top[0]
        if st >= KB.WEAK and e['id'] != 'complaint_how':
            cat, dept = e['category'], e['dept']
        store.log_turn(s['sid'], 'consult', e['id'] if st >= KB.WEAK else None, '담당자 상담 요청', st, 0, cat)
        r = _consult_form(s, text, cat, dept, '(AI 사전 안내 없음: 사용자가 담당자 상담을 직접 요청)', '내용 확인 및 후속 연락')
        r['ui']['meta'] = {'mode': 'consult'}
        return r
    if intent == 'chitchat':
        return _resp(s, [_msg('네, 궁금하신 내용을 말씀해 주세요. 요금·프로그램·단체예약·불편사항 등을 도와드립니다.')], HOME_CHIPS, meta={'mode': 'chitchat'})
    # RAG: 질문 이해로 얻은 검색어까지 합쳐 후보 근거 수집 -> LLM이 근거로만 답변
    if use_llm:
        cand = {}
        for q in [text] + ([u['search_query']] if u and u['search_query'] else []):
            for sc, ent in KB.search(q, 4):
                if sc >= 0.12 and (ent['id'] not in cand or sc > cand[ent['id']][0]):
                    cand[ent['id']] = (sc, ent)
        ranked = sorted(cand.values(), key=lambda x: -x[0])[:3]
        if ranked:
            passages = [(n + 1, ent['title'], KB.render(ent), ent['as_of']) for n, (sc, ent) in enumerate(ranked)]
            res = llm.answer(text, passages)
            if res:
                used = [ranked[n - 1][1] for n in res['used']]
                main = used[0]
                need_staff = any(x['needs_staff'] or x['kind'] == 'complaint' for x in used)
                store.log_turn(s['sid'], 'answer', main['id'], main['title'], ranked[0][0], 0 if need_staff else 1, main['category'], mode='llm')
                msg = _answer_message(s, main, text, text=res['text'], gen='llm', entries=used)
                return _kb_reply(s, main, text, msg=msg, mode='llm')
    st, e = top[0]
    if _LIVE_RE.search(text) and not re.search(r'우천|비가|비 오|눈|기상악화|프로그램', text):
        # 실시간 정보(잔여 객실·예약상태·오늘 날씨 등)는 AI가 알 수 없음 -> 확답하지 않고 담당 안내
        store.log_turn(s['sid'], 'escalate', None, None, st, 0, '기타', question=text)
        r = _escalate_prompt(s, text, '실시간 정보(잔여·예약상태·날씨 등)는 AI가 확인할 수 없음')
        r['ui']['meta'] = {'mode': 'escalate'}
        return r
    if st >= KB.STRONG and not KB.kw_hit(text, e):
        st = KB.WEAK  # 키워드 근거 없이 유사도만 높은 경우: 확답하지 않고 되묻기
    if st >= KB.STRONG:
        store.log_turn(s['sid'], 'answer', e['id'], e['title'], st, 0 if e['needs_staff'] else 1, e['category'], mode='template')
        return _kb_reply(s, e, text)
    if st >= KB.WEAK:
        store.log_turn(s['sid'], 'suggest', None, None, st, 0, top[0][1]['category'], question=text)
        opts = [_opt(x['title'], 'kb:' + x['id']) for sc, x in top if sc >= KB.WEAK * 0.6][:3]
        opts.append(_opt('담당자 상담 요청', 'act:consult'))
        s['last_q'] = text; s['mode'] = 'confirm_consult'; s['ctx'] = {'reason': 'AI가 근거자료로 확정하기 어려움(유사도 낮음)'}
        return _resp(s, [_msg('질문의 의도를 정확히 확인하고 싶어요. 혹시 아래 중 찾으시는 내용인가요?')], opts, meta={'mode': 'suggest'})
    store.log_turn(s['sid'], 'escalate', None, None, st, 0, '기타', question=text)
    r = _escalate_prompt(s, text, 'AI가 근거자료를 찾지 못함')
    r['ui']['meta'] = {'mode': 'escalate'}
    return r

def _kb_reply(s, e, question, msg=None, mode='template'):
    msg = msg or _answer_message(s, e, question)
    meta = {'mode': mode, 'kb': e['id']}
    s['mode'] = None; s['last_q'] = question
    if e['kind'] == 'group':
        opts = [_opt('단체 상담 시작하기', 'act:group'), _opt('다른 질문하기', 'act:reset')]
        return _resp(s, [msg], opts, feedback=True, meta=meta)
    if e['needs_staff'] or e['kind'] == 'complaint':
        s['ctx'] = {'question': question, 'category': e['category'], 'dept': e['dept'], 'ai_answer': msg['text'], 'needs_check': '담당자 확인 필요: ' + e['title']}
        s['mode'] = 'confirm_consult'
        return _resp(s, [msg], [_opt('담당자 상담 요청', 'act:consult'), _opt('다른 질문하기', 'act:reset')], feedback=True, meta=meta)
    related = [x for sc, x in KB.search(question, 4)[1:] if sc >= KB.WEAK][:2]
    opts = [_opt(x['title'], 'kb:' + x['id']) for x in related] + [_opt('담당자 상담 요청', 'act:consult')]
    return _resp(s, [msg], opts, feedback=True, meta=meta)

def _action(s, name):
    if name == 'reset':
        s['mode'] = None; s['slots'] = {}; s['step'] = None
        return _resp(s, [_msg('네, 다른 질문을 입력해 주세요.')], HOME_CHIPS)
    if name == 'group':
        return _start_group(s, '')
    if name == 'tour':
        return _tour(s)
    if name == 'discount':
        red = KB.pricing.get('reduction') or []
        if s.get('quote') and s['slots'].get('nights') and red:
            s['mode'] = 'group_quote'
            return _resp(s, [_msg('해당하시는 감면 대상을 눌러 주세요. 선택하신 객실 기준 예상 감면액을 보여드립니다. (대상은 객실 이용료에만 적용됩니다)')], [_opt(x['name'], 'red:' + x['name']) for x in red] + [_opt('견적 화면 계속', 'act:quote_back')])
        e = next((x for x in KB.entries if x['id'] == 'discount'), None)
        if not e:
            return _resp(s, [_msg('감면 기준 정보가 아직 등록되지 않았습니다. 담당자에게 문의해 주세요.')], HOME_CHIPS)
        return _resp(s, [_answer_message(s, e, '감면 기준')], HOME_CHIPS)
    if name == 'quote_back' and s.get('quote'):
        return _resp(s, [_msg('견적 화면으로 돌아왔습니다. 이어서 진행해 주세요.')], _quote_opts(s))
    if name == 'penalty':
        st = s['slots'].get('start')
        return _penalty(s, st) if st else _ask_penalty_date(s)
    if name == 'modify':
        return _resp(s, [_msg('어떤 항목을 수정하시겠어요?')], [_opt(STEP_LABEL[k], 'mod:' + k) for k in STEPS if not (k == 'room' and s['slots'].get('nights') == 0) and not (k == 'kids' and (not KB.pricing.get('meal_tiers') or not s['slots'].get('meals')))])
    if name == 'email':
        return _resp(s, [_msg('받으실 이메일 주소를 입력해 주세요. 상담 결과와 일정표·견적을 보내드립니다.')], form={'type': 'email'})
    if name == 'consult':
        if s['mode'] in ('group_quote',) and s.get('quote'):
            sl = s['slots']
            q = s['quote']
            summ = '단체 이용 상담: {} / 예상 견적 {}'.format(_slots_summary(sl), q['total_text'])
            s['ctx'] = {'question': summ, 'category': '단체예약', 'dept': 'GROUP', 'ai_answer': quotelib.quote_text(q),
                        'needs_check': '객실·프로그램·대관 실제 가능 여부 확인, 최종 금액 확정', 'kind': 'group'}
            form = {'type': 'consult', 'kind': 'group', 'category': '단체예약', 'dept_name': KB.dept_name('GROUP'), 'summary': summ}
            s['mode'] = 'consult'
            return _resp(s, [_msg('단체예약 상담 요청을 만들어 드릴게요. 희망 연락방법과 시간을 선택해 주세요. 담당자는 위 조건을 이미 알고 연락드리므로 처음부터 다시 묻지 않습니다.')], form=form)
        q = s.get('last_q') or ''
        if s['mode'] == 'confirm_consult' and s['ctx'].get('question'):
            c = s['ctx']
            return _consult_form(s, c['question'], c['category'], c['dept'], c.get('ai_answer') or '', c.get('needs_check') or '')
        cat, dept = KB.classify(q) if q else ('민원', 'CS')
        reason = s['ctx'].get('reason') or 'AI가 확정 답변하기 어려운 사안'
        return _consult_form(s, q or '(내용을 아래에 입력해 주세요)', cat, dept, s.get('last_answer') or '(AI 사전 답변 없음)', reason)
    return _resp(s, [_msg('요청을 이해하지 못했습니다. 질문을 입력해 주세요.')], HOME_CHIPS)

# ---------------- 상담 접수 / 이메일 ----------------
def _digits(x): return re.sub(r'\D', '', x or '')

def mask_phone(p):
    d = _digits(p)
    return d[:3] + '-****-' + d[-4:] if len(d) >= 8 else ('*' * len(d))

def _flags_for(s, summary, phone):
    flags = []
    if s.get('protect'): flags.append('직원보호')
    since = (datetime.datetime.now() - datetime.timedelta(days=30)).strftime('%Y-%m-%d')
    prev = store.query('SELECT id, summary, contact_phone FROM inquiries WHERE ts>=? ORDER BY ts DESC LIMIT 400', (since,))
    for p in prev:
        same = _digits(phone) and _digits(p['contact_phone']) == _digits(phone)
        if (same and jaccard(summary, p['summary']) >= 0.35) or jaccard(summary, p['summary']) >= 0.7:
            flags.append('반복문의({})'.format(p['id'])); break
    return flags

def submit_consult(data):
    s = get_session(data.get('sid'))
    c = s.get('ctx') or {}
    name = (data.get('name') or '').strip()[:40]
    method = data.get('method') or '이메일'
    phone = (data.get('phone') or '').strip()[:30]
    email = (data.get('email') or '').strip()[:100]
    if not data.get('consent'):
        return {'ok': False, 'error': '개인정보 수집·이용에 동의해 주세요.'}
    if method in ('전화', '문자') and len(_digits(phone)) < 9:
        return {'ok': False, 'error': '전화/문자 상담은 연락처가 필요합니다.'}
    if method == '이메일' and not mailer.valid_email(email):
        return {'ok': False, 'error': '이메일 상담은 올바른 이메일 주소가 필요합니다.'}
    if not name:
        return {'ok': False, 'error': '성함(또는 단체명)을 입력해 주세요.'}
    kind = c.get('kind') or ('group' if data.get('kind') == 'group' else 'consult')
    memo = (data.get('memo') or '').strip()[:500]
    summary = (data.get('summary') or c.get('question') or s.get('last_q') or '').strip()[:500]
    when = data.get('time_pref') or '가능한 가장 빠른 시간'
    if when == '직접 입력':
        when = (data.get('time_text') or '').strip()[:100] or '아무 때나'
    iid = store.new_inquiry_id()
    flags = _flags_for(s, summary, phone)
    payload = {}
    if kind == 'group':
        sl = s['slots']
        payload = {'희망일': _slots_summary(sl), '인원': sl.get('pax'), '숙박': sl.get('nights'), '연령대': sl.get('age'),
                   '프로그램': sl.get('programs'), '식사': _meal_plan_text(sl) or sl.get('meals'), '어린이·영유아': ', '.join('{} {}명'.format({'child': '어린이', 'infant_with': '영유아(보호자 동반)', 'infant_without': '영유아(보호자 미동반)'}[k], v) for k, v in (sl.get('kids') or {}).items()) or None, '객실': ', '.join('{} {}실'.format(k, v) for k, v in (sl.get('room_counts') or {}).items()) or sl.get('rooms') or sl.get('room'), '대관': _hall_plan_text(sl) or sl.get('hall'), '기타요청': sl.get('notes'),
                   '예상금액': (s.get('quote') or {}).get('total_text')}
    store.execute('INSERT INTO inquiries(id,ts,kind,category,dept,status,summary,question,ai_answer,needs_check,method,time_pref,contact_name,contact_phone,contact_email,memo,payload,flags,sid) '
                  'VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                  (iid, store.now(), kind, c.get('category') or ('단체예약' if kind == 'group' else '민원'), c.get('dept') or ('GROUP' if kind == 'group' else 'CS'), '접수',
                   summary, s['history'][-1] if s['history'] else summary, (c.get('ai_answer') or s.get('last_answer') or '')[:3000],
                   c.get('needs_check') or '', method, when, name, phone, email, memo, json.dumps(payload, ensure_ascii=False, default=str),
                   ','.join(flags), s['sid']))
    store.mark_converted(s['sid'], kind)
    s['inquiry_ids'].append(iid)
    s['mode'] = None
    mail = None
    if email and data.get('email_copy'):
        mail = send_result_mail(s, email, iid)
    try:
        notify_staff(iid, c.get('dept') or ('GROUP' if kind == 'group' else 'CS'), kind, summary, c, payload, flags, name, phone, email, method, when, memo)
    except Exception:
        pass  # 담당자 알림 실패가 접수를 막지 않도록 함(접수 내용은 관리자 화면에 저장됨)
    dept = KB.dept_name(c.get('dept') or 'CS')
    msg = '상담 요청이 접수되었습니다. (접수번호 {})\n요청하신 시간({})에 최대한 맞춰 {}으로 연락드리겠습니다. 해당 시간에 상담이 어려운 경우 담당자가 확인 후 가능한 일정을 안내드릴 수 있습니다.'.format(iid, when, method)
    return {'ok': True, 'id': iid, 'message': msg, 'dept': dept, 'mail': mail, 'flags': flags}

def notify_staff(iid, dept_id, kind, summary, c, payload, flags, name, phone, email, method, when, memo):
    """접수 내용을 담당 업무의 내부 수신 주소(departments.json inbox = 7_담당업무.csv 연결주소)로 메일 발송."""
    d = KB.depts.get(dept_id) or KB.depts.get('CS') or {}
    to = (d.get('inbox') or '').strip()
    if not mailer.valid_email(to): return None
    L = ['[숲톡] 새 상담 요청이 접수되었습니다. (시연용 모의 메일)', '',
         '접수번호: ' + iid, '유형: ' + ('단체예약' if kind == 'group' else (c.get('category') or '민원')), '담당 업무: ' + (d.get('name') or dept_id)]
    if flags: L.append('표시: ' + ', '.join(flags))
    L += ['', '[문의 내용]', summary or '(없음)']
    if payload: L += ['', '[단체 이용 조건]'] + ['- {}: {}'.format(k, v) for k, v in payload.items() if v not in (None, '', [])]
    if c.get('ai_answer'): L += ['', '[AI 사전 답변]', c['ai_answer'][:1500]]
    if c.get('needs_check'): L += ['', '[담당자 확인 필요]', c['needs_check']]
    L += ['', '[요청자 / 희망 연락]', '성함(단체명): ' + name, '희망 연락방법: ' + method, '희망 시간: ' + when]
    if phone: L.append('연락처: ' + phone)
    if email: L.append('이메일: ' + email)
    if memo: L.append('메모: ' + memo)
    L += ['', '※ 요청자가 다시 설명하지 않도록 위 내용을 확인한 뒤 연락해 주세요. 상세 내용은 관리자 화면 > 상담 요청함에서도 볼 수 있습니다.']
    return mailer.send(to, '[숲톡] 새 상담 요청 {} · {}'.format(iid, d.get('name') or dept_id), '\n'.join(L))

def compose_mail(s, iid=None):
    lines = ['안녕하세요, 국립산림치유원 숲톡 민원AI입니다. (시연용 모의 메일)', '']
    if iid: lines += ['접수번호: ' + iid, '']
    if s.get('last_q'): lines += ['[문의 내용]', s['last_q'], '']
    if s.get('last_answer') and not s.get('quote'): lines += ['[AI 안내 내용]', s['last_answer'], '']
    if s.get('quote'): lines += ['[단체 이용 조건]', _slots_summary(s['slots']), '', quotelib.quote_text(s['quote']), '']
    lines += ['담당자가 확인 후 연락드립니다. 담당자 개인 연락처는 공개되지 않습니다.']
    return '\n'.join(lines)

def send_result_mail(s, email, iid=None):
    return mailer.send(email, '[숲톡] AI 상담 결과' + (' (접수 {})'.format(iid) if iid else ''), compose_mail(s, iid))

def send_email_only(data):
    s = get_session(data.get('sid'))
    if not data.get('consent'):
        return {'ok': False, 'error': '이메일 수신에 동의해 주세요.'}
    return send_result_mail(s, (data.get('email') or '').strip(), s['inquiry_ids'][-1] if s['inquiry_ids'] else None)

def feedback(sid, helpful):
    store.execute('INSERT INTO feedback(ts,sid,helpful) VALUES(?,?,?)', (store.now(), sid, 1 if helpful else 0))
    return {'ok': True}

