# -*- coding: utf-8 -*-
"""외부 라이브러리 없는 한국어 간이 텍스트 처리(문자 bigram 기반)."""
import re, math

_SYN = [
    ('방값', '객실요금'), ('숙박비', '객실요금'), ('숙박요금', '객실요금'), ('객실가격', '객실요금'), ('객실 가격', '객실요금'),
    ('체크인', '입실'), ('체크아웃', '퇴실'), ('숙소', '객실'), ('가격', '요금'), ('비용', '요금'), ('금액', '요금'),
    ('얼마', '요금'), ('와이파이', '와이파이'), ('wi-fi', '와이파이'), ('wifi', '와이파이'), ('티비', 'tv'),
    ('텔레비전', 'tv'), ('애완', '반려'), ('강당', '대강당'), ('회의실', '세미나실'), ('연수', '단체연수'),
]

def normalize(text):
    t = (text or '').lower().strip()
    for a, b in _SYN:
        t = t.replace(a, b)
    t = re.sub(r'(?<![가-힣a-z0-9])방(?=[에이은을도]|\s|$)', '객실', t)
    t = re.sub(r'[^0-9a-z가-힣\s]', ' ', t)
    return re.sub(r'\s+', ' ', t).strip()

def bigrams(text):
    out = []
    for w in normalize(text).split():
        if len(w) == 1:
            out.append(w)
        else:
            out.extend(w[i:i + 2] for i in range(len(w) - 1))
    return out

class TfIdf(object):
    def __init__(self, docs):
        self.docs = [bigrams(d) for d in docs]
        n = len(self.docs)
        df = {}
        for d in self.docs:
            for g in set(d):
                df[g] = df.get(g, 0) + 1
        self.idf = {g: math.log((1 + n) / (1 + c)) + 1 for g, c in df.items()}
        self.vecs = [self._vec(d) for d in self.docs]

    def _vec(self, grams):
        tf = {}
        for g in grams:
            tf[g] = tf.get(g, 0) + 1
        v = {g: (1 + math.log(c)) * self.idf.get(g, 1.0) for g, c in tf.items()}
        norm = math.sqrt(sum(x * x for x in v.values())) or 1.0
        return {g: x / norm for g, x in v.items()}

    def score(self, query):
        q = self._vec(bigrams(query))
        return [sum(w * v.get(g, 0.0) for g, w in q.items()) for v in self.vecs]

def jaccard(a, b):
    sa, sb = set(bigrams(a)), set(bigrams(b))
    if not sa or not sb:
        return 0.0
    return len(sa & sb) / float(len(sa | sb))

# 직원 보호 표현: 욕설, 또는 사람을 향한 위협만 감지한다. '벌레 죽여주세요', '칼국수', '불이 꺼져요', '찾아가는 방법' 같은 일반 표현은 감지하지 않는다.
PROTECT_PATTERNS = [
    r'씨\s*발', r'시\s*발', r'ㅅㅂ', r'ㅂㅅ', r'개\s*새끼', r'병\s*신', r'좆', r'지랄', r'미친\s*(놈|년|새끼)', r'꺼져라', r'닥쳐',
    r'(너|니|너희|당신|네놈|직원|담당자|사장|원장|새끼|놈|년).{0,12}(죽여|죽인다|죽일|죽이겠|패버|때려|박살|가만\s*(안|두지))',
    r'(찾아가서|찾아갈테니|찾아가겠다).{0,10}(죽|패|때|박살|가만)', r'불\s*(질러|지르겠)', r'칼\s*(들고|로\s*(찌|죽))', r'폭탄\s*(설치|터)',
]

def protect_hit(text):
    t = text or ''
    return any(re.search(p, t) for p in PROTECT_PATTERNS)


def mask_pii(t):
    """질문·답변에 섞인 개인정보(전화·이메일·주민번호·긴 숫자·'○○님')를 저장 전에 가린다."""
    t = str(t or '')
    t = re.sub(r'\d{6}\s*-\s*[1-4]\d{6}', '[주민번호]', t)
    t = re.sub(r'01[016789][-.\s]?\d{3,4}[-.\s]?\d{4}', '[전화]', t)
    t = re.sub(r'0\d{1,2}[-.\s]\d{3,4}[-.\s]\d{4}', '[전화]', t)
    t = re.sub(r'[\w.+-]+@[\w-]+\.[\w.-]+', '[이메일]', t)
    t = re.sub(r'(?<!\d)\d{10,16}(?!\d)', '[번호]', t)
    t = re.sub(r'([가-힣]{1})[가-힣]{1,2}(?=\s?(님|고객님|선생님|담당자님|팀장님|과장님))', r'\1○○', t)
    return t

