    top = q("SELECT title, COUNT(*) n FROM chat_log WHERE title IS NOT NULL AND intent IN ('answer','kb_choice')" + w + " GROUP BY title ORDER BY n DESC LIMIT 10")
    cats = q("SELECT COALESCE(category,'기타') c, COUNT(*) n FROM sessions WHERE 1=1" + w + " GROUP BY c ORDER BY n DESC")
    dept = q("SELECT dept, COUNT(*) n FROM inquiries WHERE 1=1" + w + " GROUP BY dept ORDER BY n DESC")
    for d in dept: d['name'] = KB.dept_name(d['dept'])
    done = q("SELECT ts, done_ts FROM inquiries WHERE done_ts IS NOT NULL" + w)
    hrs = []
    for r in done:
        a = datetime.datetime.strptime(r['ts'], '%Y-%m-%d %H:%M:%S'); b = datetime.datetime.strptime(r['done_ts'], '%Y-%m-%d %H:%M:%S')
        hrs.append((b - a).total_seconds() / 3600.0)
    fb = q('SELECT COUNT(*) n, COALESCE(SUM(helpful),0) h FROM feedback WHERE 1=1' + w)[0]
    since = (datetime.date.today() - datetime.timedelta(days=13)).strftime('%Y-%m-%d')
    daily = q("SELECT substr(ts,1,10) d, SUM(CASE WHEN converted=0 AND answered>=1 THEN 1 ELSE 0 END) ai, SUM(converted) conv, COUNT(*) n FROM sessions WHERE substr(ts,1,10)>=?" + w + " GROUP BY d ORDER BY d", (since,))
    llm_n = q("SELECT COUNT(*) n FROM chat_log WHERE mode='llm'" + w)[0]['n']
    tpl_n = q("SELECT COUNT(*) n FROM chat_log WHERE mode='template'" + w)[0]['n']
    protect = q("SELECT COUNT(*) n FROM chat_log WHERE flag='protect'" + w)[0]['n']
    repeat = q("SELECT COUNT(*) n FROM inquiries WHERE flags LIKE '%반복문의%'" + w)[0]['n']
    pending = q("SELECT COUNT(*) n FROM inquiries WHERE status!='연락완료'" + w)[0]['n']
    pct = lambda a, b: round(100.0 * a / b, 1) if b else 0.0
    return {
        'total': total, 'ai_resolved': ai, 'ai_resolved_pct': pct(ai, total), 'converted': conv, 'converted_pct': pct(conv, total),
        'group': group, 'turns': turns, 'ai_success_pct': pct(ok, turns), 'top': top, 'categories': cats, 'departments': dept,
        'avg_hours': round(sum(hrs) / len(hrs), 1) if hrs else None, 'satisfaction_pct': pct(fb['h'], fb['n']), 'feedback_n': fb['n'],
        'daily': daily, 'protect': protect, 'repeat': repeat, 'pending': pending,
        'llm_answers': llm_n, 'template_answers': tpl_n,
        'faq_approved': q("SELECT COUNT(*) n FROM faq_runtime WHERE status='승인'")[0]['n'], 'faq_pending': q("SELECT COUNT(*) n FROM faq_runtime WHERE status='대기'")[0]['n'],
        'faq_uses': q("SELECT COUNT(*) n FROM chat_log WHERE kb_id LIKE 'u\\_%' ESCAPE '\\' AND intent IN ('answer','kb_choice')" + w)[0]['n'], 'unanswered_open': len(unanswered()['items']),
        'saved_minutes_assumed': ai * 3, 'assumption': '담당자 연결 없이 해결된 문의 1건당 전화·대기 3분 절감 가정(시범 적용 시 실측 필요)',
        'is_real_only': real_only,
        'mock_notice': '시연용 모의 로그가 포함된 수치입니다. 실제 성과가 아니라 시범 적용 시 측정할 KPI 예시입니다.' if not real_only else '이 화면에서 직접 시연한 데이터만 표시합니다.'}

def inquiries(qs):
    status = (qs.get('status') or [''])[0]; kind = (qs.get('kind') or [''])[0]
    sql = 'SELECT * FROM inquiries WHERE 1=1'; args = []
    if status: sql += ' AND status=?'; args.append(status)
    if kind: sql += ' AND kind=?'; args.append(kind)
    if (qs.get('real') or ['0'])[0] == '1': sql += ' AND is_mock=0'
    sql += ' ORDER BY ts DESC LIMIT 200'
    rows = store.query(sql, tuple(args))
    for r in rows:
        r['dept_name'] = KB.dept_name(r['dept'])
        r['phone_masked'] = mask_phone(r['contact_phone']) if r['contact_phone'] else ''
        try: r['payload'] = json.loads(r['payload'] or '{}')
        except Exception: r['payload'] = {}
    return rows

def set_status(iid, status):
    if status not in ('접수', '확인중', '연락완료'):
        return {'ok': False}
    done = store.now() if status == '연락완료' else None
    store.execute('UPDATE inquiries SET status=?, done_ts=? WHERE id=?', (status, done, iid))
    return {'ok': True}

def voc():
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'data', 'voc_summary.json')
    with open(p, encoding='utf-8') as f:
        return json.load(f)

def outbox():
    return store.query('SELECT id, ts, to_addr, subject, mode, status FROM outbox ORDER BY id DESC LIMIT 100')

def quote_html(s):
    q = s['quote']
    rows = ''.join('<tr><td>{}</td><td>{}</td><td class=r>{}</td><td class=r>{}</td><td>{}</td></tr>'.format(
        html.escape(l['item']), html.escape(str(l['qty'])), '{:,}'.format(l['unit']), '{:,}'.format(l['amount']), html.escape(l['note'])) for l in q['lines'])
    sched = ''.join('<h3>{}일차 {}</h3><ul>{}</ul>'.format(d['day'], html.escape(d['date']), ''.join('<li><b>{}</b> {}</li>'.format(i['time'], html.escape(i['title'])) for i in d['items'])) for d in q['schedule'])
    page = '''<!doctype html><html lang=ko><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>단체 이용 예상 견적서(예시)</title>
<style>body{font-family:"Malgun Gothic","Apple SD Gothic Neo",sans-serif;max-width:760px;margin:24px auto;padding:0 16px;color:#222}h1{font-size:22px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:6px 8px;font-size:14px}th{background:#eef3ee}.r{text-align:right}.tot{font-size:18px;font-weight:700;text-align:right;margin:12px 0}.warn{background:#fff7e0;border:1px solid #e0c060;padding:10px;font-size:13px}@media print{button{display:none}}</style>
<h1>국립산림치유원 단체 이용 예상 견적서 <small>(시연용 · 모의데이터)</small></h1><p>@@SUMMARY@@</p>@@SCHED@@
<table><tr><th>항목</th><th>수량</th><th>단가</th><th>금액</th><th>비고</th></tr>@@ROWS@@</table>
<div class=tot>합계 @@TOTAL@@ (1인당 약 @@PP@@)</div><div class=warn>@@DISC@@</div><p><button onclick="print()">인쇄 / PDF로 저장</button></p></html>'''
    from .chat import _slots_summary
    for k, v in (('@@SUMMARY@@', html.escape(_slots_summary(s['slots']))), ('@@SCHED@@', sched), ('@@ROWS@@', rows), ('@@TOTAL@@', q['total_text']),
                 ('@@PP@@', q['per_person_text']), ('@@DISC@@', html.escape(q['disclaimer']))):
        page = page.replace(k, v)
    return page


# ---------------- 질문 축적: 답변 못 한 질문 -> 직원 답변 작성 -> 고객지원팀 승인 -> 지식베이스 반영 ----------------
STOP = set('있나요 가능한가요 알려주세요 알려 주세요 어떻게 되나요 문의 합니다 하고 싶어요 싶은데요 궁금합니다 궁금해요 어디 무엇 뭐가'.split())

def _keywords(text, n=8):
    words = re.findall(r'[가-힣A-Za-z0-9]{2,}', normalize(text))
    freq = {}
    for w in words:
        if w not in STOP:
            freq[w] = freq.get(w, 0) + 1
    return [w for w, _ in sorted(freq.items(), key=lambda x: (-x[1], -len(x[0])))][:n]

def _handled_texts():
    out = []
    for r in store.query("SELECT question, examples FROM faq_runtime WHERE status IN ('대기','승인')"):
        out.append(r['question'] or '')
        out.extend(x for x in (r['examples'] or '').split(';') if x)
    return out

def unanswered(qs=None, limit=300):
    """AI가 근거를 못 찾거나 되물은 질문을 비슷한 것끼리 묶어 많이 들어온 순으로 보여 준다(이미 FAQ로 등록 중인 것은 제외)."""
    rows = store.query("SELECT ts, question, is_mock FROM chat_log WHERE question IS NOT NULL AND intent IN ('escalate','suggest') ORDER BY id DESC LIMIT ?", (limit,))
    done = _handled_texts()
    clusters = []
    for r in rows:
        q = (r['question'] or '').strip()
        if not q:
            continue
        for c in clusters:
            if jaccard(q, c['question']) >= 0.5:
                c['count'] += 1
                if len(c['samples']) < 4 and q not in c['samples']: c['samples'].append(q)
                break
        else:
            clusters.append({'question': q, 'count': 1, 'last_ts': r['ts'], 'samples': [q], 'mock': bool(r['is_mock'])})
    out = []
    for c in clusters:
        if any(jaccard(c['question'], t) >= 0.5 for t in done):
            continue
        cat, dept = KB.classify(c['question'])
        c['category'], c['dept'], c['dept_name'] = cat, dept, KB.dept_name(dept)
        c['keywords'] = _keywords(' '.join(c['samples']))
        out.append(c)
    out.sort(key=lambda c: (-c['count'], c['last_ts']), reverse=False)
    out.sort(key=lambda c: -c['count'])
    return {'items': out, 'depts': [{'id': k, 'name': v['name']} for k, v in KB.depts.items()]}

def faq_list():
    rows = store.query('SELECT * FROM faq_runtime ORDER BY ts DESC LIMIT 300')
    for r in rows:
        r['dept_name'] = KB.dept_name(r['dept'])
        r['uses'] = store.query("SELECT COUNT(*) n FROM chat_log WHERE kb_id=? AND intent IN ('answer','kb_choice')", (r['id'],))[0]['n']
    return {'items': rows, 'approver_pw_required': bool(os.environ.get('SUMTALK_FAQ_APPROVER_PW'))}

def faq_draft(d):
    """직원이 답변을 작성해 FAQ 초안(승인 대기)으로 올린다. 개인정보는 자동으로 가린다."""
    q = mask_pii(str(d.get('question') or '').strip())[:300]
    a = mask_pii(str(d.get('answer') or '').strip())[:1500]
    if len(q) < 4: return {'ok': False, 'error': '질문을 입력해 주세요.'}
    if len(a) < 10: return {'ok': False, 'error': '답변을 10자 이상 입력해 주세요.'}
    dept = d.get('dept') if d.get('dept') in KB.depts else 'CS'
    ex = [mask_pii(x.strip()) for x in str(d.get('examples') or '').replace('\n', ';').split(';') if x.strip()]
    ex = [q] + [x for x in ex if x != q][:6]
    kws = [x.strip() for x in str(d.get('keywords') or '').replace(',', ';').split(';') if x.strip()] or _keywords(' '.join(ex) + ' ' + a, 8)
    cat = str(d.get('category') or '').strip() or KB.classify(q)[0]
    title = mask_pii(str(d.get('title') or '').strip())[:60] or q[:40]
    day = datetime.datetime.now().strftime('%Y%m%d')
    n = store.query("SELECT COUNT(*) n FROM faq_runtime WHERE id LIKE ?", ('u_%s_%%' % day,))[0]['n'] + 1
    fid = 'u_{}_{:03d}'.format(day, n)
    store.execute('INSERT INTO faq_runtime(id,ts,title,question,answer,category,dept,keywords,examples,status,author) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
                  (fid, store.now(), title, q, a, cat, dept, ';'.join(kws), ';'.join(ex), '대기', str(d.get('author') or '담당자')[:30]))
    return {'ok': True, 'id': fid}

def faq_decide(d):
    """고객지원팀 담당자의 승인/반려. 승인 즉시 지식베이스에 반영(다음 질문부터 사용)."""
    fid, dec = d.get('id'), d.get('decision')
    if dec not in ('승인', '반려'): return {'ok': False, 'error': '승인 또는 반려만 선택할 수 있습니다.'}
    approver = str(d.get('approver') or '').strip()
    if not approver: return {'ok': False, 'error': '승인자(고객지원팀 담당자) 이름을 입력해 주세요.'}
    need = os.environ.get('SUMTALK_FAQ_APPROVER_PW', '')
    if need and str(d.get('approver_pw') or '') != need: return {'ok': False, 'error': '승인 비밀번호가 올바르지 않습니다.'}
    if not store.query('SELECT 1 FROM faq_runtime WHERE id=?', (fid,)): return {'ok': False, 'error': 'FAQ를 찾을 수 없습니다.'}
    if dec == '승인' and d.get('answer'):      # 승인자가 문구를 다듬은 경우
        store.execute('UPDATE faq_runtime SET answer=? WHERE id=?', (mask_pii(str(d['answer']).strip())[:1500], fid))
    store.execute('UPDATE faq_runtime SET status=?, approver=?, decided_ts=?, reason=? WHERE id=?', (dec, approver[:30], store.now(), str(d.get('reason') or '')[:200], fid))
    KB.reload_runtime()
    return {'ok': True}

