# -*- coding: utf-8 -*-
import sqlite3, os, json, threading, time, datetime

DB = os.environ.get('SUMTALK_DB', os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'data', 'sumtalk.db'))
_lock = threading.RLock()

SCHEMA = '''
CREATE TABLE IF NOT EXISTS sessions(sid TEXT PRIMARY KEY, ts TEXT, first_text TEXT, category TEXT, answered INTEGER DEFAULT 0,
  turns INTEGER DEFAULT 0, converted INTEGER DEFAULT 0, kind TEXT, is_mock INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS chat_log(id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, sid TEXT, intent TEXT, kb_id TEXT, title TEXT,
  score REAL, resolved INTEGER, category TEXT, flag TEXT, is_mock INTEGER DEFAULT 0, mode TEXT);
CREATE TABLE IF NOT EXISTS inquiries(id TEXT PRIMARY KEY, ts TEXT, kind TEXT, category TEXT, dept TEXT, status TEXT DEFAULT '접수',
  summary TEXT, question TEXT, ai_answer TEXT, needs_check TEXT, method TEXT, time_pref TEXT, contact_name TEXT, contact_phone TEXT,
  contact_email TEXT, memo TEXT, payload TEXT, flags TEXT, sid TEXT, done_ts TEXT, is_mock INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, to_addr TEXT, subject TEXT, body TEXT, mode TEXT, status TEXT, is_mock INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS faq_runtime(id TEXT PRIMARY KEY, ts TEXT, title TEXT, question TEXT, answer TEXT, category TEXT, dept TEXT, keywords TEXT,
  examples TEXT, status TEXT DEFAULT '대기', author TEXT, approver TEXT, decided_ts TEXT, reason TEXT, is_mock INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, sid TEXT, helpful INTEGER, is_mock INTEGER DEFAULT 0);
'''

def now():
    return datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')

def conn():
    c = sqlite3.connect(DB, timeout=15, check_same_thread=False)
    c.row_factory = sqlite3.Row
    return c

def init():
    os.makedirs(os.path.dirname(os.path.abspath(DB)), exist_ok=True)
    with _lock:
        c = conn(); c.executescript(SCHEMA)
        for col in ('mode TEXT', 'question TEXT'):    # 이전 버전 DB 호환
            try:
                c.execute('ALTER TABLE chat_log ADD COLUMN ' + col)
            except sqlite3.OperationalError:
                pass
        c.commit(); c.close()

def execute(sql, args=()):
    with _lock:
        c = conn()
        try:
            cur = c.execute(sql, args); c.commit(); return cur.lastrowid
        finally:
            c.close()

def query(sql, args=()):
    with _lock:
        c = conn()
        try:
            return [dict(r) for r in c.execute(sql, args).fetchall()]
        finally:
            c.close()

def new_inquiry_id():
    day = datetime.datetime.now().strftime('%Y%m%d')
    n = query("SELECT COUNT(*) n FROM inquiries WHERE id LIKE ?", ('SK-%s-%%' % day,))[0]['n'] + 1
    return 'SK-{}-{:03d}'.format(day, n)

# ---- 세션/로그 ----
def touch_session(sid, text):
    if not query('SELECT 1 FROM sessions WHERE sid=?', (sid,)):
        execute('INSERT INTO sessions(sid,ts,first_text,turns) VALUES(?,?,?,0)', (sid, now(), (text or '')[:200]))
    execute('UPDATE sessions SET turns=turns+1 WHERE sid=?', (sid,))

def log_turn(sid, intent, kb_id, title, score, resolved, category, flag=None, mode=None, question=None):
    from .nlp import mask_pii          # 답변 못 한 질문은 개인정보를 가린 뒤 저장(질문 축적용)
    q = mask_pii(question)[:300] if question else None
    execute('INSERT INTO chat_log(ts,sid,intent,kb_id,title,score,resolved,category,flag,mode,question) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
            (now(), sid, intent, kb_id, title, score, resolved, category, flag, mode, q))
    if resolved:
        execute('UPDATE sessions SET answered=answered+1, category=COALESCE(category,?) WHERE sid=?', (category, sid))
    else:
        execute('UPDATE sessions SET category=COALESCE(category,?) WHERE sid=?', (category, sid))

def mark_converted(sid, kind):
    execute('UPDATE sessions SET converted=1, kind=? WHERE sid=?', (kind, sid))

