# -*- coding: utf-8 -*-
import json, os, re
from .nlp import TfIdf, normalize

BASE = os.environ.get('SUMTALK_DATA') or os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'data')   # 시험 시 SUMTALK_DATA로 모의 데이터 폴더 지정

def _load(name):
    with open(os.path.join(BASE, name), encoding='utf-8') as f:
        return json.load(f)

def won(n):
    return '{:,}원'.format(int(round(n)))

class KnowledgeBase(object):
    STRONG = 0.34
    WEAK = 0.20

    def __init__(self):
        self.pricing = _load('pricing.json')
        self.depts = {d['id']: d for d in _load('departments.json')['departments']}
        self.entries = _load('kb.json')['entries']
        try:   # 기관 내부 자료(tools/import_kb.py 결과): 담당자가 승인했고 국민 공개용인 항목만 사용
            extra = [e for e in _load('kb_import.json')['entries'] if e.get('status') == 'approved' and e.get('audience', 'public') == 'public']
        except (IOError, OSError, ValueError):
            extra = []
        self._base = self.entries + extra
        self.reload_runtime()

    def reload_runtime(self):
        """직원이 작성하고 고객지원팀이 승인한 FAQ(DB)를 합쳐 검색 색인을 다시 만든다. 승인 즉시 다음 질문부터 반영."""
        runtime = []
        try:
            from . import store
            for r in store.query("SELECT * FROM faq_runtime WHERE status='승인' ORDER BY ts"):
                runtime.append({'id': r['id'], 'category': r['category'] or '기타', 'dept': r['dept'] or 'CS', 'title': r['title'], 'examples': [x for x in (r['examples'] or '').split(';') if x],
                                'keywords': [x for x in (r['keywords'] or '').split(';') if x], 'answer': r['answer'], 'source': '직원 작성·고객지원팀 승인 FAQ',
                                'as_of': (r['decided_ts'] or r['ts'] or '')[:10], 'kind': 'info', 'realtime': False, 'needs_staff': False, 'mock': bool(r['is_mock']), 'photos': [], 'status': 'approved', 'runtime': True})
        except Exception:
            runtime = []     # DB가 아직 준비되지 않았거나 테이블이 없으면 기본 FAQ만 사용
        self.entries = self._base + runtime
        self.__dict__.pop('_kwdf', None)      # 키워드 빈도 캐시 초기화
        docs = []
        for e in self.entries:
            docs.append(' '.join([e['title']] + e['examples'] + e['keywords'] * 2))
        self.index = TfIdf(docs)

    def dept_name(self, dept_id):
        return self.depts.get(dept_id, {}).get('name', '고객지원·민원 담당')

    @property
    def rules(self):
        r = dict(self.pricing.get('rules') or {})
        r.setdefault('group_min_pax', 10); r.setdefault('weekend_days', [4, 5]); r.setdefault('weekend_surcharge_rate', 0.2); r.setdefault('discounts', []); r.setdefault('holidays', []); r.setdefault('peak_season', None)
        return r

    @property
    def is_mock(self):
        return any(e.get('mock') for e in self.entries) or '모의' in str(self.pricing.get('as_of', ''))

    def tables(self):
        p = self.pricing
        r = self.rules
        wd = '월화수목금토일'
        days = '·'.join(wd[i] for i in r['weekend_days'])
        note = ('※ {}요일 숙박은 {}% 가산됩니다.'.format(days, int(round(r['weekend_surcharge_rate'] * 100)))) if r['weekend_surcharge_rate'] else ''
        two_tier = any(x.get('price_peak') for x in p['rooms'])
        if two_tier:
            ps = r.get('peak_season')
            note = '※ 성수기{}와 주말({}요일 및 법정공휴일 전일) 숙박은 \'성수기·주말\' 요금이 적용됩니다. 침구류 추가 요청 시 1만원이 추가됩니다(만 36개월 미만은 인원수에서 제외).'.format(
                '({}~{})'.format(ps[0].replace('-', '/').lstrip('0'), ps[1].replace('-', '/').lstrip('0')) if ps else '', days)
        return {
            '{GROUP_MIN}': str(r['group_min_pax']), '{WEEKEND_NOTE}': note,
            '{ROOM_TABLE}': '\n'.join(('· {}{} : 비수기 주중 {} / 성수기·주말 {}'.format(x['name'], ' (' + x['detail'] + ')' if x.get('detail') else '', won(x['price']), won(x['price_peak'])) if x.get('price_peak') else '· {} : {}'.format(x['name'], won(x['price']))) for x in p['rooms']),
            '{MEAL_TABLE}': self._meal_text(),
            '{PROGRAM_TABLE}': '\n'.join('· {}({}분) : {}'.format(g['name'], g['minutes'], won(g['price'])) for g in p['programs']),
            '{PENALTY_TABLE}': self._penalty_table(), '{DISCOUNT_TABLE}': self._discount_table(),
            '{HALL_TABLE}': '\n'.join('· {} : {}{}'.format(h['name'], won(h['price']), ' (추가 1시간당 ' + won(h['extra']) + ')' if h.get('extra') else '') for h in p['halls']),
        }

    def _penalty_table(self):
        pen = self.pricing.get('penalty') or []
        keys = []
        for x in pen:
            k = (x['target'], x['season'], x['daytype'])
            if k not in keys: keys.append(k)
        out = []
        for tg, se, dy in keys:
            rows = sorted([x for x in pen if (x['target'], x['season'], x['daytype']) == (tg, se, dy)], key=lambda x: -x['days'])
            parts = []
            for i, x in enumerate(rows):
                r = '전액 환급' if x['rate'] == 0 else '{:g}% 공제'.format(x['rate'])
                if i == 0:
                    parts.append('{}일 전까지 {}'.format(x['days'], r))
                elif x['days'] == 0:
                    parts.append('당일 {}'.format(r))
                else:
                    hi = rows[i - 1]['days'] - 1
                    parts.append(('{}일 전'.format(x['days']) if hi == x['days'] else '{}~{}일 전'.format(hi, x['days'])) + ' ' + r)
            label = ('식사 이용료' if tg == '식사' else '시설·프로그램 이용료') + ('' if se == '공통' else ' ' + se) + ('' if dy == '공통' else ' ' + dy)
            out.append('· [{}] {}'.format(label, ' / '.join(parts)))
        return '\n'.join(out)

    def _discount_table(self):
        return '\n'.join('· {}({}) : 비수기 주중 {:g}% / 성수기·주말 {:g}% — 증빙: {}'.format(x['name'], x['basis'], x['rate_off'], x['rate_peak'], x['proof']) for x in (self.pricing.get('reduction') or []))

    def table_data(self):
        """표시용 표 구조(화면에서 표로 그림). 키는 답변 안의 자리표시자."""
        p, r = self.pricing, self.rules
        two = any(x.get('price_peak') for x in p['rooms'])
        if two:
            room = {'head': ['객실', '구성', '비수기 주중', '성수기·주말'], 'rows': [[x['name'], x.get('detail') or '', won(x['price']), won(x.get('price_peak') or x['price'])] for x in p['rooms']]}
        else:
            room = {'head': ['객실', '요금'], 'rows': [[x['name'], won(x['price'])] for x in p['rooms']]}
        hall_extra = any(h.get('extra') for h in p['halls'])
        hall = {'head': ['시설', '기본 요금(2시간)'] + (['추가 1시간당'] if hall_extra else []),
                'rows': [[h['name'], won(h['price'])] + ([won(h['extra']) if h.get('extra') else '-'] if hall_extra else []) for h in p['halls']]}
        out = {'{ROOM_TABLE}': [room], '{HALL_TABLE}': [hall],
               '{MEAL_TABLE}': self._meal_tables(),
               '{PROGRAM_TABLE}': [{'head': ['프로그램', '시간', '1인 요금'], 'rows': [[g['name'], '{}분'.format(g['minutes']), won(g['price'])] for g in p['programs']]}]}
        red = p.get('reduction') or []
        out['{DISCOUNT_TABLE}'] = [{'head': ['감면 대상', '기준', '비수기 주중', '성수기·주말', '증빙서류'],
                                    'rows': [[x['name'], x['basis'], '{:g}%'.format(x['rate_off']), '{:g}%'.format(x['rate_peak']), x['proof']] for x in red]}] if red else []
        out['{PENALTY_TABLE}'] = self._penalty_tables()
        return out

    def _meal_text(self):
        p = self.pricing
        t = '\n'.join('· {} : {}'.format(m['name'], won(m['price'])) for m in p['meals'])
        mt = p.get('meal_tiers') or []
        if mt:
            t += '\n[식비 구분(1인 1식)]\n' + '\n'.join('· {}({}{}) : {}'.format(x['name'], x['basis'], (', ' + x['guardian']) if x['guardian'] else '', '무료' if x['price'] == 0 else won(x['price'])) for x in mt)
        return t

    def _meal_tables(self):
        p = self.pricing
        mt = p.get('meal_tiers') or []
        if not mt:
            return [{'head': ['식사', '1인 요금'], 'rows': [[m['name'], won(m['price'])] for m in p['meals']]}]
        out = []
        if len({m['price'] for m in p['meals']}) > 1:
            out.append({'head': ['식사', '성인 1인 요금'], 'rows': [[m['name'], won(m['price'])] for m in p['meals']]})
        out += [{'title': '식비 구분(1인 1식)', 'head': ['구분', '연령', '보호자', '이용료'],
                'rows': [[x['name'], x['basis'], x['guardian'] or '-', '무료' if x['price'] == 0 else won(x['price'])] for x in mt]}]
        return out

    def _penalty_tables(self):
        pen = self.pricing.get('penalty') or []
        res = []
        fac = [x for x in pen if x['target'] == '시설프로그램']
        if fac:
            groups = []
            for x in fac:
                k = (x['season'], x['daytype'])
                if k not in groups: groups.append(k)
            days = sorted({x['days'] for x in fac}, reverse=True)
            def cell(g, d):
                rows = sorted([x for x in fac if (x['season'], x['daytype']) == g], key=lambda x: -x['days'])
                for x in rows:
                    if d >= x['days']:
                        return '전액 환급' if x['rate'] == 0 else '{:g}% 공제'.format(x['rate'])
                return '-'
            head = ['취소 시점'] + [' '.join(y for y in g if y != '공통') or '공통' for g in groups]
            rws = [[('사용일 {}일 전까지'.format(d) if i == 0 else ('사용 당일' if d == 0 else '{}일 전'.format(d)))] + [cell(g, d) for g in groups] for i, d in enumerate(days)]
            res.append({'title': '시설·프로그램 이용료', 'head': head, 'rows': rws})
        meal = sorted([x for x in pen if x['target'] == '식사'], key=lambda x: -x['days'])
        if meal:
            rws = []
            for i, x in enumerate(meal):
                lab = '사용일 {}일 전까지'.format(x['days']) if i == 0 else ('사용 당일' if x['days'] == 0 else ('{}일 전'.format(x['days']) if meal[i - 1]['days'] - 1 == x['days'] else '{}~{}일 전'.format(meal[i - 1]['days'] - 1, x['days'])))
                rws.append([lab, '전액 환급' if x['rate'] == 0 else '{:g}% 공제'.format(x['rate'])])
            res.append({'title': '식사 이용료', 'head': ['취소 시점', '공제·환급'], 'rows': rws})
        return res

    def blocks(self, entry):
        """답변을 글(text)과 표(table) 조각으로 나눈다. 표가 없으면 빈 목록(글만 표시)."""
        text, td = entry['answer'], self.table_data()
        pat = re.compile('(' + '|'.join(re.escape(k) for k in td) + ')')
        parts, out, has = pat.split(text), [], False
        for part in parts:
            if part in td:
                for t in td[part]:
                    out.append(dict(t, type='table')); has = True
            else:
                t = part
                for k, v in self.tables().items():
                    t = t.replace(k, v)
                t = t.strip('\n')
                if t.strip():
                    out.append({'type': 'text', 'text': t})
        return out if has else []

    def render(self, entry):
        text = entry['answer']
        for k, v in self.tables().items():
            text = text.replace(k, v)
        return text

    def search(self, query, top=3):
        sims = self.index.score(query)
        nq = normalize(query)
        res = []
        if not hasattr(self, '_kwdf'):
            self._kwdf = {}
            for e in self.entries:
                for k in set(normalize(k) for k in e['keywords'] if normalize(k)):
                    self._kwdf[k] = self._kwdf.get(k, 0) + 1
        for i, e in enumerate(self.entries):
            # 여러 항목에 공통으로 쓰이는 일반 키워드(예: 요금)는 가중치를 낮춘다
            hits = sum((0.5 if self._kwdf.get(k, 1) >= 3 else 1.0) for k in set(normalize(k) for k in e['keywords']) if k and k in nq)
            kw = min(1.0, hits / 2.0)
            s = 0.6 * sims[i] + 0.4 * kw * (1.0 if sims[i] > 0.05 else 0.5)
            res.append((s, e))
        res.sort(key=lambda x: -x[0])
        return [(round(s, 3), e) for s, e in res[:top]]

    def kw_hit(self, query, e):
        """질문에 이 항목의 키워드가 하나라도 들어 있는가(유사도만으로 확답하는 것을 막는 안전장치)."""
        nq = normalize(query)
        return any(normalize(k) and normalize(k) in nq for k in e['keywords'])

    def classify(self, text):
        """질문 -> (카테고리, 담당업무ID). 검색 상위 항목 기준, 약하면 고객지원."""
        s, e = self.search(text, 1)[0]
        if s >= self.WEAK:
            return e['category'], e['dept']
        return '민원', 'CS'

