# -*- coding: utf-8 -*-
"""GitHub Pages(서버 없는 정적 호스팅)용 API 어댑터. 브라우저 안의 Pyodide에서 실행되며,
server.py와 같은 경로·같은 응답을 돌려줍니다. (대화 엔진·데이터는 서버 버전과 동일한 코드)
- 데이터베이스는 브라우저 메모리에만 있어 새로고침하면 처음 상태로 돌아갑니다(시연용).
- 이메일은 실제 발송되지 않고 '발송함'에만 기록됩니다. LLM은 연결되지 않습니다."""
import json, sys, types, time
from urllib.parse import urlparse, parse_qs

# 정적 환경에 없는 모듈은 빈 껍데기로 대체(SMTP·TLS는 사용하지 않음)
for _n in ('ssl',):
    if _n not in sys.modules:
        try:
            __import__(_n)
        except ImportError:
            m = types.ModuleType(_n); m.create_default_context = lambda *a, **k: None; sys.modules[_n] = m

from engine import store, chat, admin_api

ADMIN_PW = 'demo1234'
TOKENS = {}

def startup():
    store.init()
    chat.KB.reload_runtime()
    if not store.query('SELECT 1 FROM sessions WHERE is_mock=1 LIMIT 1'):
        from engine import seed_mock
        seed_mock.run()
    return 'ok'

def _out(obj, status=200):
    return json.dumps({'status': status, 'type': 'json', 'body': json.dumps(obj, ensure_ascii=False, default=str)}, ensure_ascii=False)

def handle(method, url, body, auth):
    u = urlparse(url); p = u.path
    try:
        d = json.loads(body) if body else {}
    except Exception:
        d = {}
    tok = (auth or '').replace('Bearer ', '')
    is_admin = tok in TOKENS and TOKENS[tok] > time.time()
    try:
        if method == 'POST':
            if p == '/api/chat': return _out(chat.handle(d.get('sid'), d.get('message'), d.get('label')))
            if p == '/api/consult': return _out(chat.submit_consult(d))
            if p == '/api/email': return _out(chat.send_email_only(d))
            if p == '/api/feedback': return _out(chat.feedback(d.get('sid'), bool(d.get('helpful'))))
            if p == '/api/admin/login':
                if str(d.get('password', '')) == ADMIN_PW:
                    t = 'st%x' % int(time.time() * 1000); TOKENS[t] = time.time() + 8 * 3600
                    return _out({'ok': True, 'token': t})
                return _out({'ok': False, 'error': '비밀번호가 올바르지 않습니다.'}, 401)
            if p.startswith('/api/admin/'):
                if not is_admin: return _out({'error': '관리자 로그인이 필요합니다.'}, 401)
                if p == '/api/admin/faq/draft': return _out(admin_api.faq_draft(d))
                if p == '/api/admin/faq/decide': return _out(admin_api.faq_decide(d))
                if p == '/api/admin/status': return _out(admin_api.set_status(d.get('id'), d.get('status')))
            return _out({'error': 'not found'}, 404)
        # GET
        if p.startswith('/api/admin/'):
            if not is_admin: return _out({'error': '관리자 로그인이 필요합니다.'}, 401)
            q = parse_qs(u.query)
            if p == '/api/admin/stats': return _out(admin_api.stats(q.get('real', ['0'])[0] == '1'))
            if p == '/api/admin/inquiries': return _out(admin_api.inquiries(q))
            if p == '/api/admin/voc': return _out(admin_api.voc())
            if p == '/api/admin/unanswered': return _out(admin_api.unanswered(q))
            if p == '/api/admin/faq': return _out(admin_api.faq_list())
            if p == '/api/admin/outbox': return _out(admin_api.outbox())
            if p == '/api/admin/llm':
                from engine import llm
                return _out(llm.status())
            return _out({'error': 'not found'}, 404)
        if p == '/api/config':
            from engine import llm
            return _out({'name': '숲톡 민원AI', 'llm': llm.enabled(), 'smtp': False, 'mock': chat.KB.is_mock, 'default_admin_pw': True, 'static': True})
        if p.startswith('/quote/'):
            s = chat.SESSIONS.get(p[7:])
            if not s or not s.get('quote'):
                return json.dumps({'status': 404, 'type': 'html', 'body': '견적이 없습니다.'}, ensure_ascii=False)
            return json.dumps({'status': 200, 'type': 'html', 'body': admin_api.quote_html(s)}, ensure_ascii=False)
        return _out({'error': 'not found'}, 404)
    except Exception as e:
        return _out({'error': '처리 중 오류가 발생했습니다: %r' % (e,)}, 500)

